data.iecDecl:
ST_Ausstattung: STRUCT
	Box2 : BOOL;
	Abluftventilator : BOOL;
	Luftaufbereiter : BOOL;
	SensorFrischluft : BOOL;
	SensorAbluftBox1 : BOOL;
	SensorAbluftBox2 : BOOL;
	SensorTrockenluft : BOOL;
	SensorStocktemp : BOOL;
	EndlagenVhdBoxenklappe1 : BOOL;
	EndlagenVhdBoxenklappe2 : BOOL;
END_STRUCT;

ST_IoTestDigitalOut: STRUCT
	doFrgLuftaufber : BOOL;
	doFrgBox1 : BOOL;
	doFrgBox2 : BOOL;
	doFrgAbluftventilator : BOOL;
	doFrgVentilator		  : BOOL;
END_STRUCT;

ST_KlappenBoxen: STRUCT
	Laufzeit : UDINT;
END_STRUCT;

ST_Aktor_Allgemein: STRUCT
	Box : ARRAY[1..2] OF ST_Aktor_Box;
	Warmluftofen : fbBoxenWLO;	(* Warmluftofen Logik *)
	Heizregister : fbHeizregister;	(* Heizregister Logik *)
	rVentilatorSollwert : REAL;
	rLuftaufbereiterSollwert : REAL;
	eStatusVentilator : eStatus;
	eStatusLuftaufbereiter : eStatus;
	xFrgVentilator : BOOL;
	xFrgLuftaufbereiter : BOOL;
	xFrgAbluftventilator : BOOL;
	xQuitFehler : BOOL;
	xLuftaufbNachlauf : BOOL;   (* Ventilator-Nachlauf Luftaufbereitung aktiv (Auskuehl/Betriebsmeldung) *)
	uRestAuskuehlzeitLuftaufb : UINT;
END_STRUCT;

ST_ParLuftaufber: STRUCT
	Typ : UINT;
	VerzWetterwechsel : UDINT;
	TempVorgabeSoll : REAL;	(* °C Solltemperatur – NEU *)
	Hysterese : REAL;
	AutomatikbetriebEin : BOOL;
	DauerbetriebEin : BOOL;
	Aus : BOOL;
	SaettigungFrischluftEin : REAL;
	DrehzahlVorgabeMin : REAL;
	DrehzahlVorgabeMax : REAL;
	P : REAL;	(* P Anteil Regler *)
	I : REAL;	(* I Anteil Regler *)
	D : REAL;	(* D Anteil Regler *)
	Auskuehlzeit : UDINT;
	VerzBetriebsmeldung : UDINT;
	BetriebsmeldungVorh : BOOL;
END_STRUCT;

ST_ParVentilator: STRUCT
 	DrehzahlMin : REAL;
	DrehzahlMax : REAL;
	DrehzahlBeiAuskuehlphase : REAL;
	DrzUmschaltung : REAL;
	DrehzahlFixLuftaufbereiter : REAL;
	DrehzahlFixFrischluft : REAL;
	DrehzahlStrombegrenzung : REAL;
	DrehzahlLeistungsreduziert : REAL;	
	ZeitRampeUp : UDINT;
	ZeitRampeDown : UDINT;
END_STRUCT;

ST_ParBoxen: STRUCT
	StellungKlappe1 : eStellungKlappeBoxen;
	StellungKlappe2 : eStellungKlappeBoxen;
	xBoxAktiv : BOOL;
	NameBox : STRING[ 32 ];
	Trockengut : eTrockengut;
	Aus : BOOL;
	DauerbetriebEin : BOOL;
	IntervallbetriebEin : BOOL;
	NachtrocknungEin : BOOL;
	StocktemperaturEin : BOOL;
	IntervallbetriebZeiten : ARRAY[0..23] OF BOOL;
	NachtrocknungZeiten : ARRAY[0..23] OF BOOL;
	AktuelleTrockengutFeuchte : UINT;
	StocktemperaturSoll : REAL;	(* Bediener-Sollwert Stocktemperatur [°C] *)
	StocktemperaturHysterese : REAL;
END_STRUCT;

ST_Alarm: STRUCT
	ArrWarnung : ARRAY[0..63] OF BOOL;
	ArrFehler : ARRAY[0..63] OF BOOL;
	ArrSystem : ARRAY[0..32] OF BOOL;
END_STRUCT;

ST.xhtml:p:
(* ================================================================================ File : IOMappingCyclic.st Project : CControl_Lite Controller : Schneider / EcoStruxure Machine Expert HVAC Author : RIG Automation Created : 2026-03-17 Version : V0.02 Description : Hauptprogramm für die I/O-Anbindung CControl_Lite
Diese Programmversion bildet die aktuell im neuen ST-Code vorgesehenen digitalen und analogen Ein-/Ausgänge.
Implementiert sind: - Einlesen der digitalen Eingänge - Einlesen und Aufbereitung der analogen Eingänge - Filterung der Frischlufttemperatur über gleitenden Mittelwert - Lineare Skalierung der analogen Rohwerte - Ausgabe digitaler Freigaben - Ausgabe analoger Sollwerte - I/O-Testbetrieb mit direkter Aktoransteuerung
================================================================================ Change History -------------------------------------------------------------------------------- Version | Date | Author | Description -------------------------------------------------------------------------------- V0.00 | 2026-03-17 | RIG | Erstversion mit Grundgerüst für | Normalbetrieb und Testbetrieb ================================================================================ *)
// INIT BOOL IBN_TRUE := TRUE; IBN_FALSE := FALSE;
(* =============================================================================== EINMALIGE INITIALISIERUNG ------------------------------------------------------------------------------- Initialwerte für Parameter und Ausstattung. Diese Initialisierung erfolgt nur einmal nach dem Start der Steuerung. =============================================================================== *) IF NOT gInitDone THEN gInitDone := TRUE; END_IF;
//Fehler Quittieren gQuitErr := HMI_IN_diQuitErr;
(* =============================================================================== BETRIEBSARTUMSCHALTUNG ------------------------------------------------------------------------------- Im Normalbetrieb werden Ein-/Ausgänge durch die Programmlogik verarbeitet. Im I/O-Testbetrieb werden Ausgänge direkt aus der Teststruktur angesteuert. =============================================================================== *) IF gAktModus <> IOTEST THEN
(* =========================================================================== NORMALBETRIEB =========================================================================== *)
(* --------------------------------------------------------------------------- Digitale Eingänge einlesen --------------------------------------------------------------------------- Zuordnung der Hardware-Eingänge auf interne Prozessvariablen. --------------------------------------------------------------------------- *)
diBox1Offen := hw_di1; diBox1Geschl := hw_di2; diBox2Offen := hw_di3; diBox2Geschl := hw_di4; diBetriebLuftaufber := hw_di5; diBetriebVentilator := hw_di6;
(* --------------------------------------------------------------------------- Analoge Rohwerte einlesen und in REAL umwandeln --------------------------------------------------------------------------- *)
rFrischluftTempRaw := TO_REAL(hw_ai1); rFrischluftFeuchtRaw := TO_REAL(hw_ai2);
//Variable Fuehler, ueber HMI einstellbar IF (gBetriebsparameter.Ausstattung.SensorTrockenluft) THEN rTrockenluftTempRaw := TO_REAL(hw_ai3); rTrockenluftFeuchtRaw := TO_REAL(hw_ai4); rAbluftBox2TempRaw := 0.0; rAbluftBox2FeuchtRaw := 0.0; ELSIF (gBetriebsparameter.Ausstattung.SensorAbluftBox2) THEN rAbluftBox2TempRaw := TO_REAL(hw_ai3); rAbluftBox2FeuchtRaw := TO_REAL(hw_ai4); rTrockenluftTempRaw := 0.0; rTrockenluftFeuchtRaw := 0.0; ELSE rTrockenluftTempRaw := 0.0; rTrockenluftFeuchtRaw := 0.0; rAbluftBox2TempRaw := 0.0; rAbluftBox2FeuchtRaw := 0.0; END_IF;
rAbluftBox1TempRaw := TO_REAL(hw_ai5); rAbluftBox1FeuchtRaw := TO_REAL(hw_ai6); rStocktempRaw := TO_REAL(hw_ai7);
(* --------------------------------------------------------------------------- Frischlufttemperatur filtern --------------------------------------------------------------------------- Die Frischlufttemperatur wird mit gleitendem Mittelwert geglättet. Dies entspricht dem Prinzip der alten B&R-Steuerung. --------------------------------------------------------------------------- *) fbFrischluftTempAvg( enable := TRUE, x := rFrischluftTempRaw, nWindow_ms := gBetriebsparameter.Sensoren.FilterzeitFrischluft * 1000, nCycle_ms := 40 );
(* --------------------------------------------------------------------------- Frischlufttemperatur skalieren --------------------------------------------------------------------------- Rohwert 0..9999 -> Engineering-Wert gemäß parametriertem Messbereich. Anschließend wird der parametrierte Offset addiert. --------------------------------------------------------------------------- *)
fbFrischluftTempScal( x := fbFrischluftTempAvg.y, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.FrischlTempMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.FrischlTempMessberMax ); aiFrischluftTemp := fbFrischluftTempScal.y + gBetriebsparameter.Sensoren.OffsetFrischluftTemp;
(* --------------------------------------------------------------------------- Frischluftfeuchte skalieren --------------------------------------------------------------------------- *) fbFrischluftFeuchtScal( x := rFrischluftFeuchtRaw, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.FrischlFeuchtMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.FrischlFeuchtMessberMax ); aiFrischluftFeucht := fbFrischluftFeuchtScal.y + gBetriebsparameter.Sensoren.OffsetFrischluftFeuchte;
(* --------------------------------------------------------------------------- Trockenluft filtern --------------------------------------------------------------------------- Die Ablufttemperatur wird mit gleitendem Mittelwert geglättet. Dies entspricht dem Prinzip der alten B&R-Steuerung. --------------------------------------------------------------------------- *) fbTrockenluftTempAvg( enable := TRUE, x := rTrockenluftTempRaw, nWindow_ms := gBetriebsparameter.Sensoren.FilterzeitTrockenluft * 1000, nCycle_ms := 40 );
(* --------------------------------------------------------------------------- Trockenluft skalieren --------------------------------------------------------------------------- Aktuell werden hierfür dieselben Rohwerte wie für Abluft Box 1 verwendet, weil dies im aktuellen Projektstand so vorgesehen ist. --------------------------------------------------------------------------- *) fbTrockenluftTempScal( x := rTrockenluftTempRaw, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.TrockenlTempMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.TrockenlTempMessberMax ); aiTrockenluftTemp := fbTrockenluftTempScal.y + gBetriebsparameter.Sensoren.OffsetTrockenluftTemp;
fbTrockenluftFeuchtScal( x := rTrockenluftFeuchtRaw, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMax ); aiTrockenluftFeucht := fbTrockenluftFeuchtScal.y + gBetriebsparameter.Sensoren.OffsetTrockenluftFeuchte;
(* --------------------------------------------------------------------------- Abluft Box 1 filtern --------------------------------------------------------------------------- Die Ablufttemperatur wird mit gleitendem Mittelwert geglättet. Dies entspricht dem Prinzip der alten B&R-Steuerung. --------------------------------------------------------------------------- *) fbAbluftBox1TempAvg( enable := TRUE, x := rAbluftBox1TempRaw, nWindow_ms := gBetriebsparameter.Sensoren.FilterzeitAbluft * 1000, nCycle_ms := 40 );
(* --------------------------------------------------------------------------- Abluft Box 1 skalieren --------------------------------------------------------------------------- *) fbAbluftBox1TempScal( x := fbAbluftBox1TempAvg.y, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftTempMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.AbluftTempMessberMax ); aiAbluftBox1Temp := fbAbluftBox1TempScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox1Temp;
fbAbluftBox1FeuchtScal( x := rAbluftBox1FeuchtRaw, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMax ); aiAbluftBox1Feucht := fbAbluftBox1FeuchtScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox1Feuchte;
(* --------------------------------------------------------------------------- Abluft Box 2 filtern --------------------------------------------------------------------------- Die Ablufttemperatur wird mit gleitendem Mittelwert geglättet. Dies entspricht dem Prinzip der alten B&R-Steuerung. --------------------------------------------------------------------------- *) fbAbluftBox2TempAvg( enable := TRUE, x := rAbluftBox2TempRaw, nWindow_ms := gBetriebsparameter.Sensoren.FilterzeitAbluft * 1000, nCycle_ms := 40 );
(* --------------------------------------------------------------------------- Abluft Box 2 skalieren --------------------------------------------------------------------------- *) fbAbluftBox2TempScal( x := fbAbluftBox2TempAvg.y, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftTempMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.AbluftTempMessberMax ); aiAbluftBox2Temp := fbAbluftBox2TempScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox2Temp;
fbAbluftBox2FeuchtScal( x := rAbluftBox2FeuchtRaw, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMax ); aiAbluftBox2Feucht := fbAbluftBox2FeuchtScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox2Feuchte;
(* --------------------------------------------------------------------------- Stocktemperatur filtern --------------------------------------------------------------------------- Die Stocktemperatur wird mit gleitendem Mittelwert geglättet. Dies entspricht dem Prinzip der alten B&R-Steuerung. --------------------------------------------------------------------------- *) fbStockTempAvg( enable := TRUE, x := rStocktempRaw, nWindow_ms := gBetriebsparameter.Sensoren.FilterzeitStocktemp * 1000, nCycle_ms := 40 );
(* --------------------------------------------------------------------------- Stocktemperatur skalieren --------------------------------------------------------------------------- *) fbStocktempScal( x := fbStockTempAvg.y, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.StocktempMessberMin, x2 := 1000.0, y2 := gBetriebsparameter.Sensoren.StocktempMessberMax ); aiStocktemp := fbStocktempScal.y + gBetriebsparameter.Sensoren.OffsetStocktemp;
(* --------------------------------------------------------------------------- Digitale Ausgänge auf Hardware schreiben --------------------------------------------------------------------------- Interne Freigaben werden auf die physikalischen Ausgänge geschrieben. --------------------------------------------------------------------------- *) hw_do1 := doFrgLuftaufber; hw_do2 := doFrgBox1; hw_do3 := doFrgBox2; hw_do4 := doFrgAbluftventilator; hw_do5 := doFrgVentilator;
(* --------------------------------------------------------------------------- Analogausgang FU-Ventilator skalieren --------------------------------------------------------------------------- Sollwertbereich 0..100 % -> Hardware-Rohwert 0..1000 --------------------------------------------------------------------------- *) fbAoFuVentilatorScal( x := aoFuVentilator, x1 := 0.0, y1 := 0.0, x2 := 100.0, y2 := 1000.0 ); hw_ao1 := TO_INT(fbAoFuVentilatorScal.y);
(* --------------------------------------------------------------------------- Analogausgang Leistungsvorgabe Luftaufbereiter skalieren --------------------------------------------------------------------------- Sollwertbereich 0..100 % -> Hardware-Rohwert 0..1000 --------------------------------------------------------------------------- *) fbAoLuftaufberLeistungScal( x := aoLeistVorgLuftaufber, x1 := 0.0, y1 := 0.0, x2 := 100.0, y2 := 1000.0 ); hw_ao4 := TO_INT(fbAoLuftaufberLeistungScal.y);
(* --------------------------------------------------------------------------- Testausgänge HMI zurücksetzen --------------------------------------------------------------------------- Sobald der I/O-Testbetrieb nicht aktiv ist, werden die Test-Sollwerte der HMI vorsorglich zurückgesetzt. Dadurch bleiben keine alten Testwerte stehen. --------------------------------------------------------------------------- *)
HMI_TEST_doFrgLuftaufber := FALSE; HMI_TEST_doFrgBox1 := FALSE; HMI_TEST_doFrgBox2 := FALSE; HMI_TEST_doFrgAbluftventilator := FALSE; HMI_TEST_doFrgVentilator := FALSE;
HMI_TEST_aoFuVentilator := 0.0; HMI_TEST_aoLeistVorgLuftaufber := 0.0;
ELSE
(* =========================================================================== I/O-TESTBETRIEB =========================================================================== Im Testbetrieb werden die Hardware-Ausgänge direkt über die Teststruktur angesteuert. Eingänge und Messwerte werden für Diagnosezwecke in die Teststruktur übernommen. =========================================================================== *)
(* --------------------------------------------------------------------------- Digitale Eingänge in Teststruktur übernehmen --------------------------------------------------------------------------- *) gIoTest.DigitalIn.diBox1Offen := hw_di1; gIoTest.DigitalIn.diBox1Geschl := hw_di2; gIoTest.DigitalIn.diBox2Offen := hw_di3; gIoTest.DigitalIn.diBox2Geschl := hw_di4; gIoTest.DigitalIn.diBetriebLuftaufber := hw_di5; gIoTest.DigitalIn.diBetriebVentilator := hw_di6;
(* --------------------------------------------------------------------------- Analoge Eingänge im Testbetrieb aufbereiten --------------------------------------------------------------------------- Auch im Testbetrieb werden die Messwerte skaliert, damit am HMI direkt Engineering-Werte sichtbar sind. --------------------------------------------------------------------------- *) fbFrischluftTempAvg( enable := TRUE, x := TO_REAL(hw_ai1), nWindow_ms := gBetriebsparameter.Sensoren.FilterzeitFrischluft * 1000, nCycle_ms := 40 );
fbFrischluftTempScal( x := fbFrischluftTempAvg.y, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.FrischlTempMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.FrischlTempMessberMax ); gIoTest.AnalogIn.aiFrischluftTemp := fbFrischluftTempScal.y + gBetriebsparameter.Sensoren.OffsetFrischluftTemp;
fbFrischluftFeuchtScal( x := TO_REAL(hw_ai2), x1 := 0.0, y1 := gBetriebsparameter.Sensoren.FrischlFeuchtMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.FrischlFeuchtMessberMax ); gIoTest.AnalogIn.aiFrischluftFeuchte := fbFrischluftFeuchtScal.y + gBetriebsparameter.Sensoren.OffsetFrischluftFeuchte; //IBN_FALSE fbTrockenluftTempAvg( enable := TRUE, x := TO_REAL(hw_ai3), nWindow_ms := gBetriebsparameter.Sensoren.FilterzeitTrockenluft * 1000, nCycle_ms := 40 );
fbTrockenluftTempScal( x := fbTrockenluftTempAvg.y, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.TrockenlTempMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.TrockenlTempMessberMax ); gIoTest.AnalogIn.aiTrockenluftTemp := fbTrockenluftTempScal.y + gBetriebsparameter.Sensoren.OffsetTrockenluftTemp;
fbTrockenluftFeuchtScal( x := TO_REAL(hw_ai4), x1 := 0.0, y1 := gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMax ); gIoTest.AnalogIn.aiTrockenluftFeucht := fbTrockenluftFeuchtScal.y + gBetriebsparameter.Sensoren.OffsetTrockenluftFeuchte;
fbAbluftBox1TempAvg( enable := TRUE, x := TO_REAL(hw_ai3), nWindow_ms := gBetriebsparameter.Sensoren.FilterzeitAbluft * 1000, nCycle_ms := 40 );
fbAbluftBox1TempScal( x := fbAbluftBox1TempAvg.y, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftTempMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.AbluftTempMessberMax ); gIoTest.AnalogIn.aiAbluftBox1Temp := fbAbluftBox1TempScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox1Temp;
fbAbluftBox1FeuchtScal( x := TO_REAL(hw_ai4), x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMax ); gIoTest.AnalogIn.aiAbluftBox1Feucht := fbAbluftBox1FeuchtScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox1Feuchte;
fbAbluftBox2TempAvg( enable := TRUE, x := TO_REAL(hw_ai5), nWindow_ms := gBetriebsparameter.Sensoren.FilterzeitAbluft * 1000, nCycle_ms := 40 );
fbAbluftBox2TempScal( x := fbAbluftBox2TempAvg.y, x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftTempMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.AbluftTempMessberMax ); gIoTest.AnalogIn.aiAbluftBox2Temp := fbAbluftBox2TempScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox2Temp;
fbAbluftBox2FeuchtScal( x := TO_REAL(hw_ai6), x1 := 0.0, y1 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMin, x2 := 9999.0, y2 := gBetriebsparameter.Sensoren.AbluftFeuchtMessberMax ); gIoTest.AnalogIn.aiAbluftBox2Feucht := fbAbluftBox2FeuchtScal.y + gBetriebsparameter.Sensoren.OffsetAbluftBox2Feuchte;
fbStockTempAvg( enable := TRUE, x := TO_REAL(hw_ai7), nWindow_ms := gBetriebsparameter.Sensoren.FilterzeitStocktemp * 1000, nCycle_ms := 40 );
fbStocktempScal( x := TO_REAL(hw_ai7), x1 := gBetriebsparameter.Sensoren.StocktempMessberMin, y1 := 0.0, x2 := gBetriebsparameter.Sensoren.StocktempMessberMax, y2 := 100.0 ); gIoTest.AnalogIn.aiStocktemp := fbStocktempScal.y + gBetriebsparameter.Sensoren.OffsetStocktemp;
(* --------------------------------------------------------------------------- Digitale Testausgänge direkt auf Hardware schreiben --------------------------------------------------------------------------- *) hw_do1 := gIoTest.DigitalOut.doFrgLuftaufber; hw_do2 := gIoTest.DigitalOut.doFrgBox1; hw_do3 := gIoTest.DigitalOut.doFrgBox2; hw_do4 := gIoTest.DigitalOut.doFrgAbluftventilator; hw_do5 := gIoTest.DigitalOut.doFrgVentilator;
(* --------------------------------------------------------------------------- Analoge Testausgänge skalieren und auf Hardware schreiben --------------------------------------------------------------------------- *) fbAoFuVentilatorScal( x := gIoTest.AnalogOut.aoFuVentilator, x1 := 0.0, y1 := 0.0, x2 := 100.0, y2 := 1000.0 ); hw_ao1 := TO_INT(fbAoFuVentilatorScal.y);
fbAoLuftaufberLeistungScal( x := gIoTest.AnalogOut.aoLeistVorgLuftaufber, x1 := 0.0, y1 := 0.0, x2 := 100.0, y2 := 1000.0 ); hw_ao4 := TO_INT(fbAoLuftaufberLeistungScal.y);
END_IF;

data.iecDecl:
PROGRAM IOMappingCyclic

VAR
	fbFrischluftTempAvg : FB_MovAvgFlt;
	fbAbluftBox1TempAvg : FB_MovAvgFlt;
	fbAbluftBox2TempAvg : FB_MovAvgFlt;
	fbTrockenluftTempAvg : FB_MovAvgFlt;
	fbStockTempAvg : FB_MovAvgFlt;
	fbFrischluftTempScal : FB_LimScal;
	fbFrischluftFeuchtScal : FB_LimScal;
	fbAbluftBox1TempScal : FB_LimScal;
	fbAbluftBox1FeuchtScal : FB_LimScal;
	fbTrockenluftTempScal : FB_LimScal;
	fbTrockenluftFeuchtScal : FB_LimScal;
	fbAbluftBox2TempScal : FB_LimScal;
	fbAbluftBox2FeuchtScal : FB_LimScal;
	fbStocktempScal : FB_LimScal;
	fbAoFuVentilatorScal : FB_LimScal;
	fbAoLuftaufberLeistungScal : FB_LimScal;
	rFrischluftTempRaw : REAL;
	rFrischluftFeuchtRaw : REAL;
	rAbluftBox1TempRaw : REAL;
	rAbluftBox1FeuchtRaw : REAL;
	rAbluftBox2TempRaw : REAL;
	rAbluftBox2FeuchtRaw : REAL;
	rTrockenluftTempRaw : REAL;
	rTrockenluftFeuchtRaw : REAL;
	rStocktempRaw : REAL;
	gInitDone : BOOL := FALSE;
END_VAR

ST.xhtml:p:
(*
================================================================================
File        : BerechnungCyclic.st
Project     : CControl_Lite
Description :
    Basisberechnungen/Plausibilisierung Lite.
================================================================================
*)

//====================================================================================================================================================
//Berechnungen aus Fühlerwerten
//====================================================================================================================================================

//Berechnungen Frischluftsensor
//*****************************
Frischluftsensor.Freigabe							:= gBetriebsparameter.Ausstattung.SensorFrischluft; // AND (NOT alarmFehler[FEHLER_SENSOR_FRISCHLUFT] OR IBN_TRUE));
Frischluftsensor.LuftTemperatur						:= gStatusAnlage.FrischluftTemperatur;
Frischluftsensor.LuftRelFeuchte						:= gStatusAnlage.FrischluftFeuchte;
Frischluftsensor.MeterUeberAdria					:= TO_REAL(gBetriebsparameter.Allgemein.StandortHoehe);
Frischluftsensor();

gStatusAnlage.FrischluftSaettDefizit := Frischluftsensor.LuftSaettigungsdefizit;

//Berechnungen Trockenluft
//*****************************
Trockenluftsensor.Freigabe							:= gBetriebsparameter.Ausstattung.SensorTrockenluft; // AND (NOT alarmFehler[FEHLER_SENSOR_TROCKENLUFT] OR IBN_TRUE));
Trockenluftsensor.LuftTemperatur					:= gStatusAnlage.TrockenluftTemperatur;
Trockenluftsensor.LuftRelFeuchte					:= gStatusAnlage.TrockenluftFeuchte;
Trockenluftsensor.MeterUeberAdria					:= TO_REAL(gBetriebsparameter.Allgemein.StandortHoehe);
Trockenluftsensor();

gStatusAnlage.TrockenluftSaettDefizit := Trockenluftsensor.LuftSaettigungsdefizit;


//Schlechtwetter Box 1
//*****************************
fbSchlechtwetterBox1.Freigabe                      := TRUE;
fbSchlechtwetterBox1.AuswahlSensor                 := gBetriebsparameter.SchlechtwetterBoxen[1].AuswahlSensorGrenzwert;
fbSchlechtwetterBox1.FrischluftSaettigungsdefizit  := gStatusAnlage.FrischluftSaettDefizit;
fbSchlechtwetterBox1.TrockenluftSaettigungsdefizit := gStatusAnlage.TrockenluftSaettDefizit;

//Sensor gilt nur als verfuegbar, wenn auch die Berechnung plausibel ist
fbSchlechtwetterBox1.SensorFrischluftVhd  := gBetriebsparameter.Ausstattung.SensorFrischluft AND
                                             //AND NOT alarmFehler[FEHLER_SENSOR_FRISCHLUFT] IBN_TRUE
                                             Frischluftsensor.Gueltig;

fbSchlechtwetterBox1.SensorTrockenluftVhd := gBetriebsparameter.Ausstattung.SensorTrockenluft AND
                                             //AND NOT alarmFehler[FEHLER_SENSOR_TROCKENLUFT] IBN_TRUE
                                             Trockenluftsensor.Gueltig;


FOR idx := 1 TO 6 DO
	fbSchlechtwetterBox1.MaterialfeuchteStufe[idx] := gBetriebsparameter.SchlechtwetterBoxen[1].Stufe[idx].MaterialfeuchteStufe;
END_FOR;

//Stufenabhaengige Werte - StufeAktuell stammt aus dem Vorzyklus
idxStufe := fbSchlechtwetterBox1.StufeAktuell;
IF (idxStufe < 1) OR (idxStufe > 6) THEN 
	idxStufe := 1; 
END_IF;

fbSchlechtwetterBox1.GrenzwertStufeAktuell          := gBetriebsparameter.SchlechtwetterBoxen[1].Stufe[idxStufe].Saettigungsdefizit;
fbSchlechtwetterBox1.SchlechtwetterPulszeitAktuell  := gBetriebsparameter.SchlechtwetterBoxen[1].Stufe[idxStufe].SchlechtwetterZeitLauf;
fbSchlechtwetterBox1.SchlechtwetterPausezeitAktuell := gBetriebsparameter.SchlechtwetterBoxen[1].Stufe[idxStufe].SchlechtwetterZeitPause;
fbSchlechtwetterBox1.VerzWetterwechsel := gBetriebsparameter.Luftaufbereitung.VerzWetterwechsel;
fbSchlechtwetterBox1.HystereseGrenzwert := gBetriebsparameter.SchlechtwetterBoxen[1].HystereseGrenzwert;
fbSchlechtwetterBox1.MaterialfeuchteIst := gBetriebsparameter.SchlechtwetterBoxen[1].MaterialfeuchteIst;

fbSchlechtwetterBox1();

//Aktualwerte auf globale Werte schreiben
gStatusAnlage.Box[1].WetterIstSchlecht := fbSchlechtwetterBox1.WetterIstSchlecht;
gStatusAnlage.Box[1].IconWitterung := fbSchlechtwetterBox1.WetterIstSchlecht;
gStatusAnlage.Box[1].AktSchlechtwetterPuls := fbSchlechtwetterBox1.SchlechtwetterPulszeitAktuell;
gStatusAnlage.Box[1].AktSchlechtwetterPause := fbSchlechtwetterBox1.SchlechtwetterPausezeitAktuell;

// 1-Sekunden-Takt fuer Betriebsstunden
TON_SekTick(IN := NOT TON_SekTick.Q, PT := 1000);

// Betriebsstundenzaehler (zaehlt solange Box aktiv)
fbBetrStdBox1(Aktiv := gBetriebsparameter.Boxen[1].xBoxAktiv, sekTick := TON_SekTick.Q, Reset := FALSE,
              Minuten := gBstBox1Min, Stunden := gBstBox1Std);
fbBetrStdBox2(Aktiv := gBetriebsparameter.Boxen[2].xBoxAktiv, sekTick := TON_SekTick.Q, Reset := FALSE,
              Minuten := gBstBox2Min, Stunden := gBstBox2Std);

// Rest-Laufzeit Intervall/Nachtrocknung (Zeitfenster je nach Modus)
IF gBetriebsparameter.Boxen[1].NachtrocknungEin THEN
    fbRestzeitBox1(Freigabe := TRUE, AktuelleStunde := TO_USINT(sysClock.hours), AktuelleMinute := TO_USINT(sysClock.minutes),
                   ZeitfensterIn := gBetriebsparameter.Boxen[1].NachtrocknungZeiten);
ELSE
    fbRestzeitBox1(Freigabe := gBetriebsparameter.Boxen[1].IntervallbetriebEin, AktuelleStunde := TO_USINT(sysClock.hours), AktuelleMinute := TO_USINT(sysClock.minutes),
                   ZeitfensterIn := gBetriebsparameter.Boxen[1].IntervallbetriebZeiten);
END_IF;
IF gBetriebsparameter.Boxen[2].NachtrocknungEin THEN
    fbRestzeitBox2(Freigabe := TRUE, AktuelleStunde := TO_USINT(sysClock.hours), AktuelleMinute := TO_USINT(sysClock.minutes),
                   ZeitfensterIn := gBetriebsparameter.Boxen[2].NachtrocknungZeiten);
ELSE
    fbRestzeitBox2(Freigabe := gBetriebsparameter.Boxen[2].IntervallbetriebEin, AktuelleStunde := TO_USINT(sysClock.hours), AktuelleMinute := TO_USINT(sysClock.minutes),
                   ZeitfensterIn := gBetriebsparameter.Boxen[2].IntervallbetriebZeiten);
END_IF;

// ===================== BOX 1 Anzeige =====================
IF gBetriebsparameter.Boxen[1].Aus THEN
    gStatusAnlage.Box[1].AnzeigeLaufRestzeit := FALSE;
    gStatusAnlage.Box[1].TextIndexLaufzeit   := 0;

ELSIF gBetriebsparameter.Boxen[1].DauerbetriebEin THEN
    // Puls-/Pause-Restzeitanzeige (nur VISU) entfernt -> immer Betriebsstunden ("Betrieb seit")
    gStatusAnlage.Box[1].AnzeigeLaufRestzeit := TRUE;
    gStatusAnlage.Box[1].TextIndexLaufzeit   := 0;
    gStatusAnlage.Box[1].LaufRestzeitStunden := TO_INT(gBstBox1Std);
    gStatusAnlage.Box[1].LaufRestzeitMinuten := TO_INT(gBstBox1Min);

ELSIF gBetriebsparameter.Boxen[1].IntervallbetriebEin OR gBetriebsparameter.Boxen[1].NachtrocknungEin THEN
    gStatusAnlage.Box[1].AnzeigeLaufRestzeit := TRUE;
    gStatusAnlage.Box[1].LaufRestzeitStunden := TO_INT(fbRestzeitBox1.RestzeitStundenOut);
    gStatusAnlage.Box[1].LaufRestzeitMinuten := TO_INT(fbRestzeitBox1.RestzeitMinutenOut);
    IF gBetriebsparameter.Boxen[1].xBoxAktiv THEN
        gStatusAnlage.Box[1].TextIndexLaufzeit := 1;   // running in
    ELSE
        gStatusAnlage.Box[1].TextIndexLaufzeit := 2;   // pause in
    END_IF;

ELSE
    // z.B. Stocktemperatur-Betrieb: keine Restzeit
    gStatusAnlage.Box[1].AnzeigeLaufRestzeit := FALSE;
    gStatusAnlage.Box[1].TextIndexLaufzeit   := 0;
END_IF;


//Schlechtwetter Box 2
//*****************************
fbSchlechtwetterBox2.Freigabe                      := TRUE;
fbSchlechtwetterBox2.AuswahlSensor                 := gBetriebsparameter.SchlechtwetterBoxen[2].AuswahlSensorGrenzwert;
fbSchlechtwetterBox2.FrischluftSaettigungsdefizit  := gStatusAnlage.FrischluftSaettDefizit;
fbSchlechtwetterBox2.TrockenluftSaettigungsdefizit := gStatusAnlage.TrockenluftSaettDefizit;

//Sensor gilt nur als verfuegbar, wenn auch die Berechnung plausibel ist
fbSchlechtwetterBox2.SensorFrischluftVhd  := gBetriebsparameter.Ausstattung.SensorFrischluft AND
                                             //AND NOT alarmFehler[FEHLER_SENSOR_FRISCHLUFT] IBN_TRUE
                                             Frischluftsensor.Gueltig;

fbSchlechtwetterBox2.SensorTrockenluftVhd := gBetriebsparameter.Ausstattung.SensorTrockenluft AND
                                             //AND NOT alarmFehler[FEHLER_SENSOR_TROCKENLUFT] IBN_TRUE
                                             Trockenluftsensor.Gueltig;


FOR idx := 1 TO 6 DO
	fbSchlechtwetterBox2.MaterialfeuchteStufe[idx] := gBetriebsparameter.SchlechtwetterBoxen[2].Stufe[idx].MaterialfeuchteStufe;
END_FOR;

//Stufenabhaengige Werte - StufeAktuell stammt aus dem Vorzyklus
idxStufe := fbSchlechtwetterBox2.StufeAktuell;
IF (idxStufe < 1) OR (idxStufe > 6) THEN 
	idxStufe := 1; 
END_IF;

fbSchlechtwetterBox2.GrenzwertStufeAktuell          := gBetriebsparameter.SchlechtwetterBoxen[2].Stufe[idxStufe].Saettigungsdefizit;
fbSchlechtwetterBox2.SchlechtwetterPulszeitAktuell  := gBetriebsparameter.SchlechtwetterBoxen[2].Stufe[idxStufe].SchlechtwetterZeitLauf;
fbSchlechtwetterBox2.SchlechtwetterPausezeitAktuell := gBetriebsparameter.SchlechtwetterBoxen[2].Stufe[idxStufe].SchlechtwetterZeitPause;
fbSchlechtwetterBox2.VerzWetterwechsel := gBetriebsparameter.Luftaufbereitung.VerzWetterwechsel;
fbSchlechtwetterBox2.HystereseGrenzwert := gBetriebsparameter.SchlechtwetterBoxen[2].HystereseGrenzwert;
fbSchlechtwetterBox2.MaterialfeuchteIst := gBetriebsparameter.SchlechtwetterBoxen[2].MaterialfeuchteIst;

fbSchlechtwetterBox2();

//Aktualwerte auf globale Werte schreiben
gStatusAnlage.Box[2].WetterIstSchlecht := fbSchlechtwetterBox2.WetterIstSchlecht;
gStatusAnlage.Box[2].IconWitterung := fbSchlechtwetterBox2.WetterIstSchlecht;
gStatusAnlage.Box[2].AktSchlechtwetterPuls := fbSchlechtwetterBox2.SchlechtwetterPulszeitAktuell;
gStatusAnlage.Box[2].AktSchlechtwetterPause := fbSchlechtwetterBox2.SchlechtwetterPausezeitAktuell;


// ===================== BOX 2 Anzeige  =====================
IF gBetriebsparameter.Boxen[2].Aus THEN
    gStatusAnlage.Box[2].AnzeigeLaufRestzeit := FALSE;
    gStatusAnlage.Box[2].TextIndexLaufzeit   := 0;

ELSIF gBetriebsparameter.Boxen[2].DauerbetriebEin THEN
    // Puls-/Pause-Restzeitanzeige (nur VISU) entfernt -> immer Betriebsstunden ("Betrieb seit")
    gStatusAnlage.Box[2].AnzeigeLaufRestzeit := TRUE;
    gStatusAnlage.Box[2].TextIndexLaufzeit   := 0;
    gStatusAnlage.Box[2].LaufRestzeitStunden := TO_INT(gBstBox2Std);
    gStatusAnlage.Box[2].LaufRestzeitMinuten := TO_INT(gBstBox2Min);

ELSIF gBetriebsparameter.Boxen[2].IntervallbetriebEin OR gBetriebsparameter.Boxen[2].NachtrocknungEin THEN
    gStatusAnlage.Box[2].AnzeigeLaufRestzeit := TRUE;
    gStatusAnlage.Box[2].LaufRestzeitStunden := TO_INT(fbRestzeitBox2.RestzeitStundenOut);
    gStatusAnlage.Box[2].LaufRestzeitMinuten := TO_INT(fbRestzeitBox2.RestzeitMinutenOut);
    IF gBetriebsparameter.Boxen[2].xBoxAktiv THEN
        gStatusAnlage.Box[2].TextIndexLaufzeit := 1;   // running in
    ELSE
        gStatusAnlage.Box[2].TextIndexLaufzeit := 2;   // pause in
    END_IF;

ELSE
    // z.B. Stocktemperatur-Betrieb: keine Restzeit
    gStatusAnlage.Box[2].AnzeigeLaufRestzeit := FALSE;
    gStatusAnlage.Box[2].TextIndexLaufzeit   := 0;
END_IF;

(*
================================================================================
 File        : AlarmCyclic.st
 Project     : CControl_Lite
 Controller  : Schneider Electric TM173O / EcoStruxure Machine Expert HVAC
 Author      : RIG Automation
 Version     : V0.01
 Created     : 2026-05-16

 Description :
   Zentrale Alarmverarbeitung für CControl_Lite.

   Jeder Fehler wird als SR-Latch implementiert:
     - Setzen:   Fehlerbedingung aktiv
     - Rücksetzen: gQuitErr = TRUE  UND  Fehlerbedingung nicht mehr aktiv
   Solange die Ursache ansteht, kann der Fehler nicht quittiert werden.

   Fehlerklassen:
     Fehler   → latchend, führt zu gCmdAnlage.FehlerStopp (Anlage stoppt)
     Warnung  → nicht latchend, nur Anzeige (kein Stopp)

   Hinweis:
     BerechnungCyclic setzt gStatusAnlage.Aktor[AKTOR_SCHRITTKETTE] ebenfalls
     auf STATUS_STOERUNG diese Zeile dort kann entfernt werden, da
     AlarmCyclic diesen Status hier zentral verwaltet.

 Change History
--------------------------------------------------------------------------------
 Version | Date       | Author         | Description
--------------------------------------------------------------------------------
 V0.01   | 2026-05-16 | RIG Automation | Erstversion
================================================================================
*)


// =============================================================================
// 1) Fehlerbedingungen ermitteln
//    Plausibilitätsgrenzen identisch zu BerechnungCyclic.
//    Nur aktiv wenn entsprechender Sensor laut Ausstattung vorhanden.
// =============================================================================

// F01 Sensor Frischluft
 xF_SensorFrischluft :=
    gBetriebsparameter.Ausstattung.SensorFrischluft AND (
        (aiFrischluftTemp  < gBetriebsparameter.Sensoren.FrischlTempMessberMin) OR (aiFrischluftTemp   > gBetriebsparameter.Sensoren.FrischlTempMessberMax)  OR
        (aiFrischluftFeucht < gBetriebsparameter.Sensoren.FrischlFeuchtMessberMin) OR (aiFrischluftFeucht > gBetriebsparameter.Sensoren.FrischlFeuchtMessberMax)
    );

// F02 Sensor Abluft Box 1
xF_SensorAbluftBox1 :=
    gBetriebsparameter.Ausstattung.SensorAbluftBox1 AND (
        (aiAbluftBox1Temp < gBetriebsparameter.Sensoren.AbluftTempMessberMin) OR (aiAbluftBox1Temp > gBetriebsparameter.Sensoren.AbluftTempMessberMax) OR
        (aiAbluftBox1Feucht < gBetriebsparameter.Sensoren.AbluftFeuchtMessberMin) OR (aiAbluftBox1Feucht > gBetriebsparameter.Sensoren.AbluftFeuchtMessberMax)
    );

// F03 Sensor Abluft Box 2 (nur wenn Box 2 vorhanden)
xF_SensorAbluftBox2 :=
    gBetriebsparameter.Ausstattung.Box2 AND
    gBetriebsparameter.Ausstattung.SensorAbluftBox2 AND (
        (aiAbluftBox2Temp   < gBetriebsparameter.Sensoren.AbluftTempMessberMin) OR (aiAbluftBox2Temp > gBetriebsparameter.Sensoren.AbluftTempMessberMax) OR
        (aiAbluftBox2Feucht < gBetriebsparameter.Sensoren.AbluftFeuchtMessberMin) OR (aiAbluftBox2Feucht > gBetriebsparameter.Sensoren.AbluftFeuchtMessberMax)
    );

// F04 Sensor Trockenluft
xF_SensorTrockenluft :=
    gBetriebsparameter.Ausstattung.SensorTrockenluft AND (
        (aiTrockenluftTemp   < gBetriebsparameter.Sensoren.TrockenlTempMessberMin) OR (aiTrockenluftTemp > gBetriebsparameter.Sensoren.TrockenlTempMessberMax) OR
        (aiTrockenluftFeucht < gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMin) OR (aiTrockenluftFeucht > gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMax)
    );

// F05 Sensor Stocktemperatur
xF_SensorStocktemp :=
    gBetriebsparameter.Ausstattung.SensorStocktemp AND (
        (aiStocktemp < gBetriebsparameter.Sensoren.StocktempMessberMin) OR (aiStocktemp > gBetriebsparameter.Sensoren.StocktempMessberMax)
    );

// F06 Laufzeit Boxenklappe 1 (Status wird von aktorenMapping gesetzt)
xF_KlappeBox1 := gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_1] = STATUS_STOERUNG;

// F07 Laufzeit Boxenklappe 2
xF_KlappeBox2 := gBetriebsparameter.Ausstattung.Box2 AND 
	(gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_2] = STATUS_STOERUNG);

// F08 Störmeldung Luftaufbereiter (Rohbedingung; Verzögerung einheitlich unten)
xF_Luftaufbereiter := gBetriebsparameter.Ausstattung.Luftaufbereiter
                      AND gAktoren.xFrgLuftaufbereiter
                      AND gBetriebsparameter.Luftaufbereitung.BetriebsmeldungVorh
                      AND NOT diBetriebLuftaufber;

// F09 Störmeldung Ventilator (Rohbedingung)
xF_Ventilator := doFrgVentilator AND NOT diBetriebVentilator;


// =============================================================================
// 2) Verzoegerung (Verzoegerungen.Fehler) + SR-Latch je Fehler
//    Setzen:    Fehler stand PT ms an
//    Rücksetzen: Quit UND Rohbedingung nicht mehr aktiv
// =============================================================================
TonF_SensorFrischluft (IN := xF_SensorFrischluft,  PT := gBetriebsparameter.Verzoegerungen.Fehler);
TonF_SensorAbluftBox1 (IN := xF_SensorAbluftBox1,  PT := gBetriebsparameter.Verzoegerungen.Fehler);
TonF_SensorAbluftBox2 (IN := xF_SensorAbluftBox2,  PT := gBetriebsparameter.Verzoegerungen.Fehler);
TonF_SensorTrockenluft(IN := xF_SensorTrockenluft, PT := gBetriebsparameter.Verzoegerungen.Fehler);
TonF_SensorStocktemp  (IN := xF_SensorStocktemp,   PT := gBetriebsparameter.Verzoegerungen.Fehler);
TonF_KlappeBox1       (IN := xF_KlappeBox1,        PT := gBetriebsparameter.Verzoegerungen.Fehler);
TonF_KlappeBox2       (IN := xF_KlappeBox2,        PT := gBetriebsparameter.Verzoegerungen.Fehler);
TonF_Luftaufbereiter  (IN := xF_Luftaufbereiter,   PT := gBetriebsparameter.Luftaufbereitung.VerzBetriebsmeldung);
TonF_Ventilator       (IN := xF_Ventilator,        PT := gBetriebsparameter.Verzoegerungen.Fehler);

IF TonF_SensorFrischluft.Q THEN 
	xFL_SensorFrischluft := TRUE;
ELSIF gQuitErr AND NOT xF_SensorFrischluft THEN 
	xFL_SensorFrischluft := FALSE; 
END_IF;

IF TonF_SensorAbluftBox1.Q THEN 
	xFL_SensorAbluftBox1 := TRUE;
ELSIF gQuitErr AND NOT xF_SensorAbluftBox1 THEN 
	xFL_SensorAbluftBox1 := FALSE; 
END_IF;

IF TonF_SensorAbluftBox2.Q THEN 
	xFL_SensorAbluftBox2 := TRUE;
ELSIF gQuitErr AND NOT xF_SensorAbluftBox2 THEN 
	xFL_SensorAbluftBox2 := FALSE; 
END_IF;

IF TonF_SensorTrockenluft.Q THEN 
	xFL_SensorTrockenluft := TRUE;
ELSIF gQuitErr AND NOT xF_SensorTrockenluft THEN 
	xFL_SensorTrockenluft := FALSE; 
END_IF;

IF TonF_SensorStocktemp.Q THEN 
	xFL_SensorStocktemp := TRUE;
ELSIF gQuitErr AND NOT xF_SensorStocktemp THEN 
	xFL_SensorStocktemp := FALSE; 
END_IF;

IF TonF_KlappeBox1.Q THEN 
	xFL_KlappeBox1 := TRUE;
ELSIF gQuitErr AND NOT xF_KlappeBox1 THEN 
	xFL_KlappeBox1 := FALSE; 
END_IF;

IF TonF_KlappeBox2.Q THEN 
	xFL_KlappeBox2 := TRUE;
ELSIF gQuitErr AND NOT xF_KlappeBox2 THEN 
	xFL_KlappeBox2 := FALSE; 
END_IF;

IF TonF_Luftaufbereiter.Q THEN 
	xFL_Luftaufbereiter := TRUE;
ELSIF gQuitErr AND NOT xF_Luftaufbereiter THEN 
	xFL_Luftaufbereiter := FALSE; 
END_IF;

IF TonF_Ventilator.Q THEN 
	xFL_Ventilator := TRUE;
ELSIF gQuitErr AND NOT xF_Ventilator THEN 
	xFL_Ventilator := FALSE; 
END_IF;   

// Sammelmeldungen (verzögert)
gAlarmBetriebLuftaufber := TonF_Luftaufbereiter.Q;
gAlarmBetriebVentilator := TonF_Ventilator.Q;
// =============================================================================
// 3) Sammelausgänge bilden
// =============================================================================

xSummeFehler :=
    xFL_SensorFrischluft OR
    xFL_SensorAbluftBox1 OR
    xFL_SensorAbluftBox2 OR
    xFL_SensorTrockenluft OR
    xFL_SensorStocktemp OR
    xFL_Luftaufbereiter OR
    xFL_KlappeBox1 OR
    xFL_KlappeBox2;

// Warnungen (nicht latchend) Erweiterungspunkt für zukünftige Warnungen
xSummeWarnung := FALSE;


// =============================================================================
// 4) Fehleraktionen
// =============================================================================

// Fehlerstopp anfordern AblaufstrgCyclic wertet gCmdAnlage.FehlerStopp aus
gCmdAnlage.FehlerStopp := xSummeFehler;

// Schrittketten-Status für HMI (zentraler Status der Anlage)
IF xSummeFehler THEN
    gStatusAnlage.Aktor[AKTOR_SCHRITTKETTE] := STATUS_STOERUNG;
END_IF;

gudTemp := fcSetBitInBitmask(gudTemp, 0);


// =============================================================================
// 5) Auf globales Meldearray kopieren
// =============================================================================

//Warnungen

//Fehler
gStatusAnlage.Alarm.ArrFehler[FEHLER_SENSOR_FRISCHLUFT] := xFL_SensorFrischluft;
gStatusAnlage.Alarm.ArrFehler[FEHLER_SENSOR_ABLUFT_BOX1] := xFL_SensorAbluftBox1;
gStatusAnlage.Alarm.ArrFehler[FEHLER_SENSOR_ABLUFT_BOX2] := xFL_SensorAbluftBox2;
gStatusAnlage.Alarm.ArrFehler[FEHLER_SENSOR_TROCKENLUFT] := xFL_SensorTrockenluft;
gStatusAnlage.Alarm.ArrFehler[FEHLER_SENSOR_STOCKTEMP] := xFL_SensorStocktemp;

gStatusAnlage.Alarm.ArrFehler[FEHLER_ENDLAGEN_BOXENKLAPPE_1] := xFL_KlappeBox1;
gStatusAnlage.Alarm.ArrFehler[FEHLER_ENDLAGEN_BOXENKLAPPE_2] := xFL_KlappeBox2;

gStatusAnlage.Alarm.ArrFehler[FEHLER_BETRIEBSMLDG_LUFTAUFBEREITER] := xFL_Luftaufbereiter;
gStatusAnlage.Alarm.ArrFehler[FEHLER_BETRIEBSMLDG_VENTILATOR] := xFL_Ventilator;

data.iecDecl:
PROGRAM AlarmCyclic

VAR
	xF_SensorFrischluft : BOOL;
	xF_SensorAbluftBox1 : BOOL;
	xF_SensorAbluftBox2 : BOOL;
	xF_SensorTrockenluft : BOOL;
	xF_SensorStocktemp : BOOL;
	xF_KlappeBox1 : BOOL;
	xF_KlappeBox2 : BOOL;
	xF_Luftaufbereiter : BOOL;
	xF_Ventilator : BOOL;
	xFL_SensorFrischluft : BOOL;
	xFL_SensorAbluftBox1 : BOOL;
	xFL_SensorAbluftBox2 : BOOL;
	xFL_SensorTrockenluft : BOOL;
	xFL_SensorStocktemp : BOOL;
	xFL_KlappeBox1 : BOOL;
	xFL_KlappeBox2 : BOOL;
	xFL_Luftaufbereiter : BOOL;
	xFL_Ventilator : BOOL;
	xSummeFehler : BOOL;
	xSummeWarnung : BOOL;
	TonF_SensorFrischluft  : TON;
    TonF_SensorAbluftBox1  : TON;
    TonF_SensorAbluftBox2  : TON;
    TonF_SensorTrockenluft : TON;
    TonF_SensorStocktemp   : TON;
    TonF_KlappeBox1        : TON;
    TonF_KlappeBox2        : TON;
    TonF_Luftaufbereiter   : TON;
    TonF_Ventilator        : TON;
END_VAR

ST.xhtml:p:
(*
================================================================================
 File        : MainControl.st
 Project     : CControl_Lite
 Controller  : Schneider / EcoStruxure Machine Expert HVAC
 Author      : RIG Automation
 Created     : 2026-04-13
 Version     : V0.01
 Description :
    Vereinfachte Ablaufsteuerung für die reduzierte CControl_Lite Variante.

    Diese Version enthält nur die tatsächlich vorhandenen Funktionen und Aktoren.
    Die Struktur orientiert sich an der Legacy-Schrittkette, wurde jedoch bewusst
    auf die im Projekt vorhandene Hardware reduziert.

    Enthalten:
      - Statusaktualisierung
      - einfache Ablaufsteuerung
      - Stillstand / Betrieb / I/O-Test
      - direkte Ansteuerlogik für vorhandene Aktoren

 Change History
 --------------------------------------------------------------------------------
 Version | Date       | Author          | Description
 --------------------------------------------------------------------------------
 V0.01   | 2026-04-13 | RIG Automation  | Initiale reduzierte Ablaufsteuerung
================================================================================
*)

// =============================================================================
// 1) Statusaktualisierung
// =============================================================================
gStatusAnlage.FrischluftTemperatur  := aiFrischluftTemp;
gStatusAnlage.FrischluftFeuchte     := aiFrischluftFeucht;
gStatusAnlage.TrockenluftTemperatur := aiTrockenluftTemp;
gStatusAnlage.TrockenluftFeuchte    := aiTrockenluftFeucht;
gStatusAnlage.AbluftBox1Temp        := aiAbluftBox1Temp;
gStatusAnlage.AbluftBox1Feuchte     := aiAbluftBox1Feucht;
gStatusAnlage.AbluftBox2Temp        := aiAbluftBox2Temp;
gStatusAnlage.AbluftBox2Feuchte     := aiAbluftBox2Feucht;
gStatusAnlage.StockTemperatur       := aiStocktemp;

// =============================================================================
// 2) Bedienbefehle auswerten
// =============================================================================
xStartFreigabe   := gCmdAnlage.Start AND gCmdAnlage.Auto;
xStopAnforderung := gCmdAnlage.Stopp;
xTestbetrieb     := gCmdAnlage.Test AND NOT gCmdAnlage.Auto;

// =============================================================================
// 3) Aktuellen Zustand übernehmen
// =============================================================================
gAktModus := nextModus;

// =============================================================================
// 4) Schrittkette
// =============================================================================
CASE gAktModus OF

    // *************************************************************************
    // STILLSTAND
    // *************************************************************************
    STILLSTAND:
        IF stateEntry THEN
            stateEntry := FALSE;
			Strombegrenzung.Freigabe	:= FALSE;
            gStatusAnlage.Aktor[AKTOR_SCHRITTKETTE] := STATUS_STILLSTAND;
        END_IF;

        // ------------------------------------------------------------
        // Stillstandslogik - nur vorhandene Aktoren
        // ------------------------------------------------------------
        gAktoren.Box[1].xSollOffen := FALSE;
        gAktoren.Box[2].xSollOffen := FALSE;

        // ------------------------------------------------------------
        // Zustandswechsel
        // ------------------------------------------------------------
        IF xStartFreigabe THEN
            nextModus := BETRIEB;
            stateEntry := TRUE;

        ELSIF xTestbetrieb THEN
            nextModus := IOTEST;
            stateEntry := TRUE;

        ELSE
            nextModus := gAktModus;
        END_IF;


    // *************************************************************************
    // BETRIEB
    // *************************************************************************
    BETRIEB:
        IF stateEntry THEN
            stateEntry := FALSE;

            gStatusAnlage.Aktor[AKTOR_SCHRITTKETTE] := STATUS_ANLAGE_IN_BETRIEB;
            hmiNutzungsdaten.LetzterModus := BETRIEB;
        END_IF;


		//Funktionsbaustein Strombegrenzung
		Strombegrenzung.Freigabe	:= TRUE;
		Strombegrenzung.AktZeit		:= TO_REAL(sysClock.hours * 100 + sysClock.minutes);

        // ------------------------------------------------------------
        // Betriebslogik - nur vorhandene Aktoren
        // ------------------------------------------------------------

        //BOX 1
        gAktoren.Box[1].xSollOffen := gBetriebsparameter.Boxen[1].xBoxAktiv;
      	//BOX 2 
        gAktoren.Box[2].xSollOffen := gBetriebsparameter.Boxen[2].xBoxAktiv;

        // ------------------------------------------------------------
        // Zustandswechsel
        // ------------------------------------------------------------
        IF xStopAnforderung OR gCmdAnlage.FehlerStopp THEN
            hmiNutzungsdaten.LetzterModus := STILLSTAND;
            nextModus := STILLSTAND;
            stateEntry := TRUE;
        ELSE
            nextModus := gAktModus;
        END_IF;


    // *************************************************************************
    // IOTEST
    // *************************************************************************
    IOTEST:
        IF stateEntry THEN
            stateEntry := FALSE;
			Strombegrenzung.Freigabe	:= FALSE;
            gStatusAnlage.Aktor[AKTOR_SCHRITTKETTE] := STATUS_TESTBETRIEB;
        END_IF;

        // NEU: keine automatische Box-Anforderung im I/O-Test
        gAktoren.Box[1].xSollOffen := FALSE;
        gAktoren.Box[2].xSollOffen := FALSE;

        // ------------------------------------------------------------
        // Zustandswechsel
        // ------------------------------------------------------------
        IF NOT xTestbetrieb THEN
            nextModus := STILLSTAND;
            stateEntry := TRUE;
        ELSE
            nextModus := gAktModus;
        END_IF;

END_CASE;

//Funktionsbausteine aufrufen
uStromBegrStart1 := (gBetriebsparameter.Strombegrenzung.StartStd * 100) + gBetriebsparameter.Strombegrenzung.StartMin;
uStromBegrStopp1 := (gBetriebsparameter.Strombegrenzung.StoppStd * 100) + gBetriebsparameter.Strombegrenzung.StoppMin;
Strombegrenzung.StartZeit1 := TO_REAL(uStromBegrStart1);
Strombegrenzung.StoppZeit1 := TO_REAL(uStromBegrStopp1);
Strombegrenzung();

(* ============================================================================
   TARIFABSCHALTUNG - Zeitfenster (Minuten des Tages 0..1439)
   ============================================================================ *)
nAktMin     := TO_UINT(sysClock.hours) * 60 + TO_UINT(sysClock.minutes);
nTarifStart := gBetriebsparameter.Tarifabschaltung.Zeitfenster.StartStd * 60
             + gBetriebsparameter.Tarifabschaltung.Zeitfenster.StartMin;
nTarifStop  := gBetriebsparameter.Tarifabschaltung.Zeitfenster.StoppStd * 60
             + gBetriebsparameter.Tarifabschaltung.Zeitfenster.StoppMin;

//Tarif-Fenster aktiv? (mit Mitternachts-Umschlag)
IF nTarifStart = nTarifStop THEN
    gCmdAnlage.xTarifAbschaltung := FALSE;                 //kein Fenster parametriert
ELSIF nTarifStart < nTarifStop THEN
    gCmdAnlage.xTarifAbschaltung := (nAktMin >= nTarifStart) AND (nAktMin < nTarifStop);
ELSE
    gCmdAnlage.xTarifAbschaltung := (nAktMin >= nTarifStart) OR  (nAktMin < nTarifStop);
END_IF;

// --- Vorlaufzeit: Luftaufbereitung/Trocknung früher abschalten -------------
nVorlaufMin := TO_UINT(gBetriebsparameter.Tarifabschaltung.VorlaufzeitAbschaltungLuftaufb / 60000); // ms -> min  (*)
IF nTarifStart >= nVorlaufMin THEN
    nTarifStartLuftaufb := nTarifStart - nVorlaufMin;
ELSE
    nTarifStartLuftaufb := 1440 + nTarifStart - nVorlaufMin;   // Tagesumschlag
END_IF;

IF nTarifStart = nTarifStop THEN
    gCmdAnlage.xTarifAbschaltungLuftaufb := FALSE;             // kein Fenster
ELSIF nTarifStartLuftaufb < nTarifStop THEN
    gCmdAnlage.xTarifAbschaltungLuftaufb := (nAktMin >= nTarifStartLuftaufb) AND (nAktMin < nTarifStop);
ELSE
    gCmdAnlage.xTarifAbschaltungLuftaufb := (nAktMin >= nTarifStartLuftaufb) OR  (nAktMin < nTarifStop);
END_IF;

gAktoren.Heizregister();
gAktoren.Warmluftofen();

data.iecDecl:
PROGRAM AblaufstrgCyclic

VAR
	stateEntry : BOOL := TRUE;
	xStartFreigabe : BOOL;
	xStopAnforderung : BOOL;
	xTestbetrieb : BOOL;
	nextModus : eBetriebsmodus := STILLSTAND;
	uStromBegrStart1 : UINT;
	uStromBegrStopp1 : UINT;
	nAktMin       : UINT;
	nTarifStart   : UINT;
	nTarifStop    : UINT;
	nVorlaufMin         : UINT;
    nTarifStartLuftaufb : UINT;
END_VAR

ST.xhtml:p:
(*
================================================================================
File        : LeistungCyclic.st
Project     : CControl_Lite
Description :
    Leistungsregelung Lite.
    Luftaufbereitung: KEINER / HEIZREGISTER / OFEN (HMI-konfigurierbar).
    EIN/AUS beider Luftaufbereitungen ueber Frischluft-Saettigungsdefizit.
    Heizregister: Leistung per PID auf Trockenlufttemperatur.
    Ofen: Solltemperatur-Vorgabe, Betriebsmeldung/Zuendzeit + Auskuehlzeit.
    FB-Aufrufe (gAktoren.Heizregister/.Warmluftofen) erfolgen in AblaufstrgCyclic,
    die Ein-/Ausgaenge werden hier beschaltet.
================================================================================
*)

CASE gAktModus OF

    STILLSTAND:
        gAktoren.xFrgVentilator       := FALSE;
        gAktoren.xFrgLuftaufbereiter  := FALSE;
        gAktoren.xFrgAbluftventilator := FALSE;

        gCmdAnlage.Leistung.DrehzahlVentilator       := gBetriebsparameter.Ventilator.DrehzahlMin;
        gCmdAnlage.Leistung.DrehzahlLuftaufbereitung := 0.0;

        //Luftaufbereitungs-FBs sperren
        gAktoren.Heizregister.Freigabe := FALSE;
        gAktoren.Warmluftofen.Freigabe := FALSE;

        xLuftaufbHystEin     := FALSE;
        xLuftaufbPidEn       := FALSE;
        rLuftaufbLeistung    := 0.0;


    BETRIEB:
        gAktoren.xFrgVentilator  := TRUE;

        //*** Drehzahlvorgabe Ventilator 1 ***
        //Basisdrehzahl: mit aktiver Luftaufbereitung -> DrehzahlFixLuftaufbereiter,
        //sonst Frischluft-Drehzahl (xFrgLuftaufbereiter aus Vorzyklus, unkritisch).
        IF gAktoren.xFrgLuftaufbereiter THEN
            rVentDrehzahlBasis := gBetriebsparameter.Ventilator.DrehzahlFixLuftaufbereiter;
        ELSE
            rVentDrehzahlBasis := gBetriebsparameter.Ventilator.DrehzahlFixFrischluft;
        END_IF;
		//Strombegrenzung
        IF Strombegrenzung.StrombegrenzungEin THEN
            IF (rVentDrehzahlBasis > gBetriebsparameter.Ventilator.DrehzahlStrombegrenzung) THEN
                gCmdAnlage.Leistung.DrehzahlVentilator := gBetriebsparameter.Ventilator.DrehzahlStrombegrenzung;
            ELSE
                gCmdAnlage.Leistung.DrehzahlVentilator := rVentDrehzahlBasis;
            END_IF;
        ELSE
            gCmdAnlage.Leistung.DrehzahlVentilator := rVentDrehzahlBasis;
        END_IF;

        (* --- Luftaufbereitung --- *)
        //Grundfreigaben der FBs (werden je Typ unten aktiviert wenn jeweilige Luftaufbereitung wirklich aktiv)
        gAktoren.Heizregister.Freigabe := FALSE;
        gAktoren.Warmluftofen.Freigabe := FALSE;

		//Ermittlung ob Trocknung aktiv (fuer Luftaufbereitung)
		//-> im Tarif-Fenster Luftaufbereitung sperren (startet Auskuehlung)
		xTrocknungAktiv := (gBetriebsparameter.Boxen[1].xBoxAktiv OR gBetriebsparameter.Boxen[2].xBoxAktiv)
		                 AND NOT gCmdAnlage.xTarifAbschaltungLuftaufb;

        CASE gBetriebsparameter.Luftaufbereitung.Typ OF

            KEINER:
                gAktoren.xFrgLuftaufbereiter := FALSE;
                xLuftaufbHystEin     := FALSE;
                xLuftaufbPidEn       := FALSE;
                rLuftaufbLeistung    := 0.0;

                fbPidLuftaufb(
                    xEn := FALSE, rPv := aiTrockenluftTemp, rSetp := 0.0,
                    xManualMode := TRUE, rManualValue := 0.0, xHold := FALSE,
                    rHighLimit := 100.0, rLowLimit := 0.0, rDeadband := 0.5,
                    xAutoTune := FALSE, rAutoTuneValue := 0.0,
                    rKp := 1.0, uiTi := 1, uiTd := 0, xReset := FALSE
                );


            HEIZREGISTER:				
                //--- EIN/AUS ueber Frischluft-Saettigungsdefizit (fbHeizregister) ---
                //Eingaenge beschalten (Aufruf erfolgt in AblaufstrgCyclic)
                gAktoren.Heizregister.Freigabe                  := xTrocknungAktiv;
                gAktoren.Heizregister.QuitFehler                := gQuitErr;
                gAktoren.Heizregister.Automatikbetrieb          := gBetriebsparameter.Luftaufbereitung.AutomatikbetriebEin;
                gAktoren.Heizregister.Dauerbetrieb              := gBetriebsparameter.Luftaufbereitung.DauerbetriebEin;
                gAktoren.Heizregister.FehlerSensorAussenluft    := NOT gBetriebsparameter.Ausstattung.SensorFrischluft;
                gAktoren.Heizregister.FrischluftSattDefizitIst  := gStatusAnlage.FrischluftSaettDefizit;
                gAktoren.Heizregister.FrischluftSattDefizitSoll := gBetriebsparameter.Luftaufbereitung.SaettigungFrischluftEin;
                gAktoren.Heizregister.Hysterese                 := gBetriebsparameter.Luftaufbereitung.Hysterese;
                gAktoren.Heizregister.UmschaltverzWitterung     := gBetriebsparameter.Luftaufbereitung.VerzWetterwechsel;
                gAktoren.Heizregister.WetterIstSchlecht         := FALSE;
                gAktoren.Heizregister.DrehzahlHeizregisterSoll  := gBetriebsparameter.Luftaufbereitung.DrehzahlVorgabeMin;

                //Freigabe aus dem FB: Dauerbetrieb=immer EIN, Automatik=Saettigungsdefizit
                xLuftaufbHystEin := gAktoren.Heizregister.FreigabeHeizregisterOut;

                IF gBetriebsparameter.Luftaufbereitung.DauerbetriebEin THEN
                    (* IMMER EIN: fixe Leistungsvorgabe (manuell), kein PID *)
                    xLuftaufbPidEn    := FALSE;
                    rLuftaufbLeistung := gCmdAnlage.Leistung.DrehzahlLuftaufbereitung;
                    fbPidLuftaufb(
                        xEn := FALSE, rPv := aiTrockenluftTemp, rSetp := 0.0,
                        xManualMode := TRUE, rManualValue := rLuftaufbLeistung, xHold := FALSE,
                        rHighLimit := gBetriebsparameter.Luftaufbereitung.DrehzahlVorgabeMax,
                        rLowLimit  := gBetriebsparameter.Luftaufbereitung.DrehzahlVorgabeMin,
                        rDeadband := 0.5, xAutoTune := FALSE, rAutoTuneValue := 0.0,
                        rKp := gBetriebsparameter.Luftaufbereitung.P,
                        uiTi := TO_UINT(gBetriebsparameter.Luftaufbereitung.I * 10.0),
                        uiTd := TO_UINT(gBetriebsparameter.Luftaufbereitung.D * 10.0),
                        xReset := FALSE
                    );
                ELSE
                    (* AUTOMATIK: EIN/AUS ueber Saettigungsdefizit (FB),
                       Leistung per PID auf Trockenlufttemperatur *)
                    xLuftaufbPidEn := xLuftaufbHystEin AND gBetriebsparameter.Ausstattung.SensorTrockenluft;
                    fbPidLuftaufb(
                        xEn            := xLuftaufbPidEn,
                        rPv            := aiTrockenluftTemp,
                        rSetp          := gBetriebsparameter.Luftaufbereitung.TempVorgabeSoll,
                        xManualMode    := NOT xLuftaufbPidEn,
                        rManualValue   := gBetriebsparameter.Luftaufbereitung.DrehzahlVorgabeMin,
                        xHold          := FALSE,
                        rHighLimit     := gBetriebsparameter.Luftaufbereitung.DrehzahlVorgabeMax,
                        rLowLimit      := gBetriebsparameter.Luftaufbereitung.DrehzahlVorgabeMin,
                        rDeadband      := 0.5, xAutoTune := FALSE, rAutoTuneValue := 0.0,
                        rKp            := gBetriebsparameter.Luftaufbereitung.P,
                        uiTi           := TO_UINT(gBetriebsparameter.Luftaufbereitung.I * 10.0),
                        uiTd           := TO_UINT(gBetriebsparameter.Luftaufbereitung.D * 10.0),
                        xReset         := gQuitErr
                    );
                    rLuftaufbLeistung := fbPidLuftaufb.rAnalog;
                END_IF;

                gAktoren.xFrgLuftaufbereiter := xLuftaufbHystEin;


            OFEN:
                xLuftaufbHystEin    := FALSE;
                xLuftaufbPidEn      := FALSE;

                //--- Warmluftofen: EIN/AUS ueber Saettigungsdefizit, Zuendzeit-/
                //    Betriebsmeldungsueberwachung, Auskuehlzeit (fbBoxenWLO) ---
                //Eingaenge beschalten (Aufruf erfolgt in AblaufstrgCyclic)
                gAktoren.Warmluftofen.Freigabe                    := xTrocknungAktiv;
                gAktoren.Warmluftofen.Automatikbetrieb            := gBetriebsparameter.Luftaufbereitung.AutomatikbetriebEin;
                gAktoren.Warmluftofen.Dauerbetrieb                := gBetriebsparameter.Luftaufbereitung.DauerbetriebEin;
                gAktoren.Warmluftofen.FehlerSensorAussenluft      := NOT gBetriebsparameter.Ausstattung.SensorFrischluft;
                gAktoren.Warmluftofen.FrischluftSattDefizitIst    := gStatusAnlage.FrischluftSaettDefizit;
                gAktoren.Warmluftofen.FrischluftSattDefizitSoll   := gBetriebsparameter.Luftaufbereitung.SaettigungFrischluftEin;
                gAktoren.Warmluftofen.Hysterese                   := gBetriebsparameter.Luftaufbereitung.Hysterese;
                gAktoren.Warmluftofen.UmschaltverzWitterung       := gBetriebsparameter.Luftaufbereitung.VerzWetterwechsel;
                gAktoren.Warmluftofen.WarmlufttemperaturVorgabe   := gBetriebsparameter.Luftaufbereitung.TempVorgabeSoll;
                gAktoren.Warmluftofen.OptionBetriebsmldgVhd       := gBetriebsparameter.Luftaufbereitung.BetriebsmeldungVorh;
                gAktoren.Warmluftofen.BetriebsmeldungWarmluftofen := diBetriebLuftaufber;
                gAktoren.Warmluftofen.VerzBetriebsmeldung         := gBetriebsparameter.Luftaufbereitung.VerzBetriebsmeldung;
                gAktoren.Warmluftofen.Auskuehlzeit                := gBetriebsparameter.Luftaufbereitung.Auskuehlzeit;
                gAktoren.Warmluftofen.QuitFehler                  := gQuitErr;
                gAktoren.Warmluftofen.WetterIstSchlecht           := FALSE;

                //Ausgaenge uebernehmen
                gAktoren.xFrgLuftaufbereiter := gAktoren.Warmluftofen.FreigabeWarmluftofenOut;
                rLuftaufbLeistung            := gAktoren.Warmluftofen.WarmlufttempSollOut;

                //PID (Heizregister) im Ofenbetrieb deaktiviert halten
                fbPidLuftaufb(
                    xEn := FALSE, rPv := aiTrockenluftTemp, rSetp := 0.0,
                    xManualMode := TRUE, rManualValue := 0.0, xHold := FALSE,
                    rHighLimit := 100.0, rLowLimit := 0.0, rDeadband := 0.5,
                    xAutoTune := FALSE, rAutoTuneValue := 0.0,
                    rKp := 1.0, uiTi := 1, uiTd := 0, xReset := FALSE
                );

        ELSE
            gAktoren.xFrgLuftaufbereiter := FALSE;
            xLuftaufbHystEin     := FALSE;
            xLuftaufbPidEn       := FALSE;
            rLuftaufbLeistung    := 0.0;

            fbPidLuftaufb(
                xEn := FALSE, rPv := aiTrockenluftTemp, rSetp := 0.0,
                xManualMode := TRUE, rManualValue := 0.0, xHold := FALSE,
                rHighLimit := 100.0, rLowLimit := 0.0, rDeadband := 0.5,
                xAutoTune := FALSE, rAutoTuneValue := 0.0,
                rKp := 1.0, uiTi := 1, uiTd := 0, xReset := FALSE
            );
        END_CASE;

        (* IO-Ausgang Luftaufbereitung *)
        IF gAktoren.xFrgLuftaufbereiter THEN
            gCmdAnlage.Leistung.DrehzahlLuftaufbereitung := rLuftaufbLeistung;
        ELSE
            gCmdAnlage.Leistung.DrehzahlLuftaufbereitung := 0.0;
        END_IF;

	    (* --- Abluftventilator: Feuchteregelung der aktiven Box --- *)
        IF gBetriebsparameter.Ausstattung.Abluftventilator THEN

            //Aktive Box bestimmen + Feuchtewert waehlen.
            //Bei nur 1 Abluftfuehler wird dieser als Ersatz fuer die andere Box genutzt.
            xAbluftBoxAktiv := FALSE;

            IF (gBetriebsparameter.Boxen[1].xBoxAktiv AND gAktoren.Box[1].xSollOffen) THEN
                IF gBetriebsparameter.Ausstattung.SensorAbluftBox1 THEN
                    rAbluftFeuchteAkt := aiAbluftBox1Feucht;
                    xAbluftBoxAktiv   := TRUE;
                ELSIF gBetriebsparameter.Ausstattung.SensorAbluftBox2 THEN
                    rAbluftFeuchteAkt := aiAbluftBox2Feucht;   //Ersatzfuehler
                    xAbluftBoxAktiv   := TRUE;
                END_IF;

            ELSIF (gBetriebsparameter.Boxen[2].xBoxAktiv AND gAktoren.Box[2].xSollOffen) THEN
                IF gBetriebsparameter.Ausstattung.SensorAbluftBox2 THEN
                    rAbluftFeuchteAkt := aiAbluftBox2Feucht;
                    xAbluftBoxAktiv   := TRUE;
                ELSIF gBetriebsparameter.Ausstattung.SensorAbluftBox1 THEN
                    rAbluftFeuchteAkt := aiAbluftBox1Feucht;   //Ersatzfuehler (nur 1 Fuehler)
                    xAbluftBoxAktiv   := TRUE;
                END_IF;
            END_IF;

            IF xAbluftBoxAktiv THEN
                //Zustandsabhaengige Hysterese (Ventilator laeuft bei hoher Feuchte)
                IF NOT gAktoren.xFrgAbluftventilator THEN
                    //EIN wenn Feuchte ueber Sollwert + Hysterese
                    IF (rAbluftFeuchteAkt >= gBetriebsparameter.Abluftventilator.FeuchteSoll
                                            + gBetriebsparameter.Abluftventilator.Hysterese) THEN
                        gAktoren.xFrgAbluftventilator := TRUE;
                    END_IF;
                ELSE
                    //AUS wenn Feuchte deutlich unter Sollwert
                    IF (rAbluftFeuchteAkt <= gBetriebsparameter.Abluftventilator.FeuchteSoll
                                            - gBetriebsparameter.Abluftventilator.Hysterese) THEN
                        gAktoren.xFrgAbluftventilator := FALSE;
                    END_IF;
                END_IF;
            ELSE
                //Keine aktive Box / kein gueltiger Wert -> Feuchteregelung aus
                gAktoren.xFrgAbluftventilator := FALSE;
            END_IF;

        ELSE
            //Kein Abluftventilator vorhanden -> Feuchtesensoren nur Anzeige
            gAktoren.xFrgAbluftventilator := FALSE;
        END_IF;


    IOTEST:
        gAktoren.xFrgVentilator       := FALSE;
        gAktoren.xFrgLuftaufbereiter  := FALSE;
        gAktoren.xFrgAbluftventilator := FALSE;
        gAktoren.Heizregister.Freigabe := FALSE;
        gAktoren.Warmluftofen.Freigabe := FALSE;

        xLuftaufbHystEin     := FALSE;
        xLuftaufbPidEn       := FALSE;
        rLuftaufbLeistung    := 0.0;


        gCmdAnlage.Leistung.DrehzahlVentilator       := 0.0;
        gCmdAnlage.Leistung.DrehzahlLuftaufbereitung := 0.0;

        fbPidLuftaufb(
            xEn := FALSE, rPv := aiTrockenluftTemp, rSetp := 0.0,
            xManualMode := TRUE, rManualValue := 0.0, xHold := FALSE,
            rHighLimit := 100.0, rLowLimit := 0.0, rDeadband := 0.5,
            xAutoTune := FALSE, rAutoTuneValue := 0.0,
            rKp := 1.0, uiTi := 1, uiTd := 0, xReset := FALSE
        );

    ELSE

        gAktoren.xFrgVentilator       := FALSE;
        gAktoren.xFrgLuftaufbereiter  := FALSE;
        gAktoren.xFrgAbluftventilator := FALSE;

        gAktoren.Heizregister.Freigabe := FALSE;
        gAktoren.Warmluftofen.Freigabe := FALSE;

        gCmdAnlage.Leistung.DrehzahlVentilator       := 0.0;
        gCmdAnlage.Leistung.DrehzahlLuftaufbereitung := 0.0;

        xLuftaufbHystEin     := FALSE;
        xLuftaufbPidEn       := FALSE;
        rLuftaufbLeistung    := 0.0;

        fbPidLuftaufb(
            xEn := FALSE, rPv := aiTrockenluftTemp, rSetp := 0.0,
            xManualMode := TRUE, rManualValue := 0.0, xHold := FALSE,
            rHighLimit := 100.0, rLowLimit := 0.0, rDeadband := 0.5,
            xAutoTune := FALSE, rAutoTuneValue := 0.0,
            rKp := 1.0, uiTi := 1, uiTd := 0, xReset := FALSE
        );
END_CASE;

(*
================================================================================
 File        : AktorenMapping.st
 Project     : CControl_Lite
 Controller  : Schneider / EcoStruxure Machine Expert HVAC
 Author      : RIG Automation
 Created     : 2026-04-03
 Version     : V0.03
 Description :
    Zyklisches Aktoren-Mapping für die Kleinsteuerung.

    Enthaltene Aktoren:
      - Boxenklappe 1
      - Boxenklappe 2
      - Ventilator 1
      - Luftaufbereiter
      - Abluftventilator

    Die Boxenklappen werden über den Funktionsbaustein fbBoxenklappe
    angesteuert.

================================================================================
 Change History
--------------------------------------------------------------------------------
 Version | Date       | Author          | Description
--------------------------------------------------------------------------------
 V0.03   | 2026-04-03 | RIG Automation  | Anpassung auf FB fbBoxenklappe
================================================================================
*)

gAktoren.xQuitFehler := gQuitErr;

(*
===============================================================================
 Boxenkonfiguration
 Die Einstellung der Boxen erfolgt ueber die HMI. Die Klappen-
 stellungen werden je nach den Vorgaben in der Einstellung geschaltet. Ein 
 gleichzeitiges belueften mehrerer Boxen ist nicht vorgesehen.
===============================================================================
 TRUE  = öffnen
 FALSE = schließen
-------------------------------------------------------------------------------
*)

//Standard: Klappen zu -> verhindert Nachhaengen, wenn eine aktive Box eine Klappe = NONE hat
xFreigabeKlappe1Out := FALSE;
xFreigabeKlappe2Out := FALSE;

IF (gAktoren.Box[1].xSollOffen OR xNotbetriebBox1) THEN

	//Klappe 1
	IF gBetriebsparameter.Boxen[1].StellungKlappe1 <> FBBOX_NONE THEN
		IF gBetriebsparameter.Boxen[1].StellungKlappe1 = FBBOX_GESCHLOSSEN THEN
			xFreigabeKlappe1Out	:= FALSE;
		ELSE
			xFreigabeKlappe1Out	:= TRUE;
		END_IF;
	END_IF;

	//Klappe 2
	IF gBetriebsparameter.Boxen[1].StellungKlappe2 <> FBBOX_NONE THEN
		IF gBetriebsparameter.Boxen[1].StellungKlappe2 = FBBOX_GESCHLOSSEN THEN
			xFreigabeKlappe2Out	:= FALSE;
		ELSE
			xFreigabeKlappe2Out	:= TRUE;
		END_IF;
	END_IF;
ELSIF (gAktoren.Box[2].xSollOffen OR xNotbetriebBox2) THEN	
	//Klappe 1
	IF gBetriebsparameter.Boxen[2].StellungKlappe1 <> FBBOX_NONE THEN
		IF gBetriebsparameter.Boxen[2].StellungKlappe1 = FBBOX_GESCHLOSSEN THEN
			xFreigabeKlappe1Out	:= FALSE;
		ELSE
			xFreigabeKlappe1Out	:= TRUE;
		END_IF;
	END_IF;
	//Klappe 2
	IF gBetriebsparameter.Boxen[2].StellungKlappe2 <> FBBOX_NONE THEN
		IF gBetriebsparameter.Boxen[2].StellungKlappe2 = FBBOX_GESCHLOSSEN THEN
			xFreigabeKlappe2Out	:= FALSE;
		ELSE
			xFreigabeKlappe2Out	:= TRUE;
		END_IF;
	END_IF;	
ELSE 
	xFreigabeKlappe1Out := FALSE;
	xFreigabeKlappe2Out := FALSE;
END_IF;

(*
===============================================================================
 BOXENKLAPPE 1
===============================================================================
 TRUE  = öffnen
 FALSE = schließen
-------------------------------------------------------------------------------
*) 

// Im IOTEST wird der FB NICHT aufgerufen -> Timer/Endlagenlogik eingefroren,
// doFrgBox1/2 bleiben stehen und werden ohnehin von IOMapping (Testzweig) überschrieben.
IF gAktModus <> IOTEST THEN
	fbBoxenklappe1(
	    Oeffnen            := xFreigabeKlappe1Out,
	    Schliessen         := NOT xFreigabeKlappe1Out,
	    EndlageOffen       := diBox1Offen,
	    EndlageGeschl      := diBox1Geschl,
	    EndlagenVhd        := gBetriebsparameter.Ausstattung.EndlagenVhdBoxenklappe1,
	    LaufzeitOeffnen    := gBetriebsparameter.KlappenBoxen[1].Laufzeit,
	    LaufzeitSchliessen := gBetriebsparameter.KlappenBoxen[1].Laufzeit,
	    Stoerung           := diBox1Offen AND diBox1Geschl,
	    QuitFehler         := gAktoren.xQuitFehler 
	);

	(* Physischer Ausgang Wechsler-Relais *)
	doFrgBox1 := fbBoxenklappe1.OeffnenOut;
END_IF;

(*
-------------------------------------------------------------------------------
 Status Boxenklappe 1
-------------------------------------------------------------------------------
*)
IF fbBoxenklappe1.FehlerLaufzeitOeffnen OR fbBoxenklappe1.FehlerLaufzeitSchliessen OR (diBox1Offen AND diBox1Geschl) THEN
    gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_1] := STATUS_STOERUNG;
ELSIF fbBoxenklappe1.OeffnenOut AND NOT (diBox1Offen OR fbBoxenklappe1.KlappeIstOffenOut) THEN
    gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_1] := STATUS_IN_BEWEGUNG;
ELSIF fbBoxenklappe1.SchliessenOut AND NOT (diBox1Geschl OR fbBoxenklappe1.KlappeIstGeschlOut) THEN
    gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_1] := STATUS_IN_BEWEGUNG;
ELSIF (diBox1Offen OR fbBoxenklappe1.KlappeIstOffenOut) THEN
    gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_1] := STATUS_OFFEN;
ELSIF (diBox1Geschl OR fbBoxenklappe1.KlappeIstGeschlOut) THEN
    gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_1] := STATUS_GESCHLOSSEN;
ELSE
    gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_1] := STATUS_UNBEKANNT;
END_IF;


(*
===============================================================================
 BOXENKLAPPE 2
===============================================================================
 TRUE  = öffnen
 FALSE = schließen
-------------------------------------------------------------------------------
*)

// Im IOTEST wird der FB NICHT aufgerufen -> Timer/Endlagenlogik eingefroren,
// doFrgBox1/2 bleiben stehen und werden ohnehin von IOMapping (Testzweig) überschrieben.
IF gAktModus <> IOTEST THEN
	fbBoxenklappe2(
	    Oeffnen            := xFreigabeKlappe2Out,
	    Schliessen         := NOT xFreigabeKlappe2Out,
	    EndlageOffen       := diBox2Offen,
	    EndlageGeschl      := diBox2Geschl,
	    EndlagenVhd        := gBetriebsparameter.Ausstattung.EndlagenVhdBoxenklappe2,
	    LaufzeitOeffnen    := gBetriebsparameter.KlappenBoxen[2].Laufzeit,
	    LaufzeitSchliessen := gBetriebsparameter.KlappenBoxen[2].Laufzeit,
	    Stoerung           := diBox2Offen AND diBox2Geschl,
	    QuitFehler         := gAktoren.xQuitFehler
	);

	(* Physischer Ausgang Wechsler-Relais *)
	doFrgBox2 := fbBoxenklappe2.OeffnenOut;
END_IF;


(*
-------------------------------------------------------------------------------
 Status Boxenklappe 2
-------------------------------------------------------------------------------
*)
IF fbBoxenklappe2.FehlerLaufzeitOeffnen OR fbBoxenklappe2.FehlerLaufzeitSchliessen OR (diBox2Offen AND diBox2Geschl) THEN
    gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_2] := STATUS_STOERUNG;
ELSIF fbBoxenklappe2.OeffnenOut AND NOT (diBox2Offen OR fbBoxenklappe2.KlappeIstOffenOut) THEN
    gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_2] := STATUS_IN_BEWEGUNG;
ELSIF fbBoxenklappe2.SchliessenOut AND NOT (diBox2Geschl OR fbBoxenklappe2.KlappeIstGeschlOut) THEN
    gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_2] := STATUS_IN_BEWEGUNG;
ELSIF (diBox2Offen OR fbBoxenklappe2.KlappeIstOffenOut) THEN
    gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_2] := STATUS_OFFEN;
ELSIF (diBox2Geschl OR fbBoxenklappe2.KlappeIstGeschlOut) THEN
    gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_2] := STATUS_GESCHLOSSEN;
ELSE
    gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_2] := STATUS_UNBEKANNT;
END_IF;


(* ============================================================================
   Klappen-Position "erreicht" je physischer Klappe
   ----------------------------------------------------------------------------
   Mit Endlagenueberwachung  -> reale Endlagen-DI
   Ohne Endlagenueberwachung -> zeitbasierter FB-Ausgang (KlappeIstOffen/Geschl)
   -> FU startet auch ohne Endlagenschalter nach Ablauf der Klappenlaufzeit,
      statt bedingungslos auf "Endlage offen" zu warten.
   ============================================================================ *)
IF gBetriebsparameter.Ausstattung.EndlagenVhdBoxenklappe1 THEN
    xKlappe1OffenErr  := diBox1Offen;
    xKlappe1GeschlErr := diBox1Geschl;
ELSE
    xKlappe1OffenErr  := fbBoxenklappe1.KlappeIstOffenOut;
    xKlappe1GeschlErr := fbBoxenklappe1.KlappeIstGeschlOut;
END_IF;

IF gBetriebsparameter.Ausstattung.EndlagenVhdBoxenklappe2 THEN
    xKlappe2OffenErr  := diBox2Offen;
    xKlappe2GeschlErr := diBox2Geschl;
ELSE
    xKlappe2OffenErr  := fbBoxenklappe2.KlappeIstOffenOut;
    xKlappe2GeschlErr := fbBoxenklappe2.KlappeIstGeschlOut;
END_IF;

xBox1EndlErreicht :=
    ((gBetriebsparameter.Boxen[1].StellungKlappe1 = FBBOX_GEOEFFNET   AND xKlappe1OffenErr)  OR
     (gBetriebsparameter.Boxen[1].StellungKlappe1 = FBBOX_GESCHLOSSEN AND xKlappe1GeschlErr) OR
      gBetriebsparameter.Boxen[1].StellungKlappe1 = FBBOX_NONE) AND
    ((gBetriebsparameter.Boxen[1].StellungKlappe2 = FBBOX_GEOEFFNET   AND xKlappe2OffenErr)  OR
     (gBetriebsparameter.Boxen[1].StellungKlappe2 = FBBOX_GESCHLOSSEN AND xKlappe2GeschlErr) OR
      gBetriebsparameter.Boxen[1].StellungKlappe2 = FBBOX_NONE);

xBox2EndlErreicht :=
    ((gBetriebsparameter.Boxen[2].StellungKlappe1 = FBBOX_GEOEFFNET   AND xKlappe1OffenErr)  OR
     (gBetriebsparameter.Boxen[2].StellungKlappe1 = FBBOX_GESCHLOSSEN AND xKlappe1GeschlErr) OR
      gBetriebsparameter.Boxen[2].StellungKlappe1 = FBBOX_NONE) AND
    ((gBetriebsparameter.Boxen[2].StellungKlappe2 = FBBOX_GEOEFFNET   AND xKlappe2OffenErr)  OR
     (gBetriebsparameter.Boxen[2].StellungKlappe2 = FBBOX_GESCHLOSSEN AND xKlappe2GeschlErr) OR
      gBetriebsparameter.Boxen[2].StellungKlappe2 = FBBOX_NONE);


(*
===============================================================================
 FU
===============================================================================

-------------------------------------------------------------------------------
*)

(* 
	============================================================================
   	Ventilator-Nachlauf Luftaufbereitung (Betriebsmeldung / Auskuehlzeit)
   	----------------------------------------------------------------------------
   	Nach Wegnahme der Freigabe darf der Ventilator NICHT sofort abschalten:
     - Betriebsmeldung vorhanden -> Ventilator bleibt EIN solange Betriebsmeldung EIN
     - keine Betriebsmeldung     -> Ventilator bleibt EIN fuer die Auskuehlzeit
	============================================================================ 
*)
TOF_LuftaufbAuskuehl(IN := gAktoren.xFrgLuftaufbereiter,
                     PT := gBetriebsparameter.Luftaufbereitung.Auskuehlzeit);

xLuftaufbNachlauf := gAktoren.xFrgLuftaufbereiter
    OR (gBetriebsparameter.Luftaufbereitung.BetriebsmeldungVorh AND diBetriebLuftaufber)
    OR (NOT  gBetriebsparameter.Luftaufbereitung.BetriebsmeldungVorh AND TOF_LuftaufbAuskuehl.Q);

// Rest/Auskühlzeit berechnen
gAktoren.uRestAuskuehlzeitLuftaufb := TO_UINT((gBetriebsparameter.Luftaufbereitung.Auskuehlzeit - TO_UDINT(TOF_LuftaufbAuskuehl.ET)) / 1000);   // ms -> s

//global Spiegeln
gAktoren.xLuftaufbNachlauf := xLuftaufbNachlauf;

//Physikalische Ventilatoranforderung der Boxen
xBoxAnf := (gAktoren.Box[1].xSollOffen AND xBox1EndlErreicht AND gBetriebsparameter.Boxen[1].xBoxAktiv)
        OR (gAktoren.Box[2].xSollOffen AND xBox2EndlErreicht AND gBetriebsparameter.Boxen[2].xBoxAktiv);

//Ventilatorfreigabe: normale Box-Anforderung ODER Nachlauf/Betriebsmeldung (übersteuert, auch bei Störung/AUS)
doFrgVentilator := (gAktoren.xFrgVentilator AND xBoxAnf) OR (xLuftaufbNachlauf AND (gAktModus <> IOTEST));


gAktoren.rVentilatorSollwert      := gCmdAnlage.Leistung.DrehzahlVentilator;
gAktoren.rLuftaufbereiterSollwert := gCmdAnlage.Leistung.DrehzahlLuftaufbereitung;

//Sollwert begrenzen wenn Freigabe Ventilator erteilt
IF (doFrgVentilator) THEN
        IF ((gBetriebsparameter.Boxen[1].xBoxAktiv AND NOT xBox1EndlErreicht)
            OR (gBetriebsparameter.Boxen[2].xBoxAktiv AND NOT xBox2EndlErreicht)) THEN
        //Klappenumschaltung: angeforderte Box noch nicht in Endlage -> Umschaltdrehzahl
        gAktoren.rVentilatorSollwert := LIMIT(
            MN := gBetriebsparameter.Ventilator.DrehzahlMin,
            IN := gBetriebsparameter.Ventilator.DrzUmschaltung,
            MX := gBetriebsparameter.Ventilator.DrehzahlMax);
    ELSIF (xLuftaufbNachlauf AND NOT (gBetriebsparameter.Boxen[1].xBoxAktiv OR gBetriebsparameter.Boxen[2].xBoxAktiv)) THEN
        //Nur die Luftaufbereitung haelt den Ventilator (Auskuehl-/Nachlaufphase):
        //Drehzahl "bei Auskuehlphase", begrenzt auf Min/Max des Luftaufbereiters
        //(diese Grenzen gelten vorrangig).
        gAktoren.rVentilatorSollwert := LIMIT(
            MN := gBetriebsparameter.Luftaufbereitung.DrehzahlVorgabeMin,
            IN := gBetriebsparameter.Ventilator.DrehzahlBeiAuskuehlphase,
            MX := gBetriebsparameter.Luftaufbereitung.DrehzahlVorgabeMax);
    ELSE
        //Bei Betrieb Ventilator auf MIN/MAX Grenzen pruefen.
        gAktoren.rVentilatorSollwert := LIMIT(IN := gAktoren.rVentilatorSollwert,
                                              MN := gBetriebsparameter.Ventilator.DrehzahlMin,
                                              MX := gBetriebsparameter.Ventilator.DrehzahlMax);
    END_IF;
ELSE
    //Keine Freigabe - Drehzahl Ventilator auf 0 setzen da sonst minimalwert in der Visu angezeigt wird
    gAktoren.rVentilatorSollwert  := 0.0;
END_IF;


(*
===============================================================================
 VENTILATOR 1
===============================================================================
 Direkte Ansteuerung:
   - digitale Freigabe
   - analoge Drehzahlvorgabe
-------------------------------------------------------------------------------
*)

IF doFrgVentilator THEN
    gStatusAnlage.Aktor[AKTOR_VENTILATOR] := STATUS_AKTIV;
ELSE
    gStatusAnlage.Aktor[AKTOR_VENTILATOR] := STATUS_NICHT_AKTIV;
END_IF;

aoFuVentilator := gAktoren.rVentilatorSollwert;

(*
===============================================================================
 LUFTAUFBEREITER
===============================================================================
 Direkte Ansteuerung
 Analoge Leistungsvorgabe analog zum Heizregister-Prinzip:
   - digitale Freigabe
   - analoger Sollwert
-------------------------------------------------------------------------------
*)

gStatusAnlage.LuftaufberTyp := gBetriebsparameter.Luftaufbereitung.Typ;


IF gAktoren.xFrgLuftaufbereiter THEN
    IF gAlarmBetriebLuftaufber THEN
        gStatusAnlage.Aktor[AKTOR_LUFTAUFBER] := STATUS_STOERUNG;
    ELSIF diBetriebLuftaufber THEN
        gStatusAnlage.Aktor[AKTOR_LUFTAUFBER] := STATUS_AKTIV;
    ELSE
        gStatusAnlage.Aktor[AKTOR_LUFTAUFBER] := STATUS_BEREIT;
    END_IF;
ELSE
    IF gAlarmBetriebLuftaufber THEN
        gStatusAnlage.Aktor[AKTOR_LUFTAUFBER] := STATUS_STOERUNG;
    ELSE
        gStatusAnlage.Aktor[AKTOR_LUFTAUFBER] := STATUS_NICHT_AKTIV;
    END_IF;
END_IF;

doFrgLuftaufber := gAktoren.xFrgLuftaufbereiter;
aoLeistVorgLuftaufber := gAktoren.rLuftaufbereiterSollwert;

(*
===============================================================================
 ABLUFTVENTILATOR
===============================================================================
 Direkte Ansteuerung
-------------------------------------------------------------------------------
*)

IF gAktoren.xFrgAbluftventilator THEN
    gStatusAnlage.Aktor[AKTOR_ABLUFTVENTILATOR] := STATUS_AKTIV;
ELSE
    gStatusAnlage.Aktor[AKTOR_ABLUFTVENTILATOR] := STATUS_NICHT_AKTIV;
END_IF;


doFrgAbluftventilator := gAktoren.xFrgAbluftventilator;

data.iecDecl:
PROGRAM AktorenMappingCyclic

VAR
	xStateEntryBox1 : BOOL := TRUE;
	uiStepBox1 : UINT := 0;
	xFehlerLaufzeitOeffnenBox1 : BOOL := FALSE;
	xFehlerLaufzeitSchliessenBox1 : BOOL := FALSE;
	xKlappeIstOffenBox1 : BOOL := FALSE;
	xKlappeIstGeschlBox1 : BOOL := FALSE;
	tonLaufzeitBox1 : TON;
	tonAnzVerzBox1 : TON;
	xStateEntryBox2 : BOOL := TRUE;
	uiStepBox2 : UINT := 0;
	xFehlerLaufzeitOeffnenBox2 : BOOL := FALSE;
	xFehlerLaufzeitSchliessenBox2 : BOOL := FALSE;
	xKlappeIstOffenBox2 : BOOL := FALSE;
	xKlappeIstGeschlBox2 : BOOL := FALSE;
	tonLaufzeitBox2 : TON;
	tonAnzVerzBox2 : TON;
	xBox1OeffnenOut : BOOL := FALSE;
	xBox1SchliessenOut : BOOL := FALSE;
	xBox2OeffnenOut : BOOL := FALSE;
	xBox2SchliessenOut : BOOL := FALSE;
	xStoerungBox1 : BOOL := FALSE;
	xStoerungBox2 : BOOL := FALSE;
	fbBoxenklappe1 : fbBoxenklappe;
	fbBoxenklappe2 : fbBoxenklappe;
	xFreigabeKlappe1Out : BOOL := FALSE;
	xFreigabeKlappe2Out : BOOL := FALSE;
	xNotbetriebBox1 : BOOL := FALSE;
	xNotbetriebBox2 : BOOL := FALSE;
	xBox1EndlErreicht : BOOL := FALSE;
	xBox2EndlErreicht : BOOL := FALSE;
	TOF_LuftaufbAuskuehl : TOF;    (* Auskuehl-/Nachlaufzeit Luftaufbereitung *)
	xLuftaufbNachlauf    : BOOL;   (* Ventilator-Nachlauf durch Luftaufbereitung aktiv *)
	xBoxAnf              : BOOL;   (* Ventilatoranforderung durch eine Box *)
	xKlappe1OffenErr  : BOOL;   (* Klappe 1 Position "offen" erreicht (DI oder zeitbasiert) *)
	xKlappe1GeschlErr : BOOL;   (* Klappe 1 Position "geschlossen" erreicht *)
	xKlappe2OffenErr  : BOOL;   (* Klappe 2 Position "offen" erreicht *)
	xKlappe2GeschlErr : BOOL;   (* Klappe 2 Position "geschlossen" erreicht *)
END_VAR

ST.xhtml:p:
(*
================================================================================
 File        : HMIMappingCyclic.st
 Project     : CControl_Lite
 Controller  : Schneider / EcoStruxure Machine Expert HVAC
 Author      : RIG Automation
 Created     : 2026-03-19
 Version     : V0.01
 Description :
    Zyklische Übergabe von Ein-/Ausgängen und aufbereiteten Messwerten an die HMI.

    Dieses Programm trennt bewusst zwischen:
      - Hardware-/Prozessabbild
      - interner Programmlogik
      - Visualisierungsdaten

    Die HMI liest ausschließlich die hier beschriebenen HMI-Variablen.
    Dadurch bleibt die Visualisierung von der eigentlichen I/O-Anbindung entkoppelt.

================================================================================
 Change History
--------------------------------------------------------------------------------
 Version | Date       | Author          | Description
--------------------------------------------------------------------------------
 V0.01   | 2026-03-19 | RIG Automation  | Initialerstellung HMI-Mapping für
                                        | digitale/analoge Ein- und Ausgänge
================================================================================
*)

(*
===============================================================================
 HMI-DATEN ZYKLISCH AKTUALISIEREN
-------------------------------------------------------------------------------
 Alle für die Visualisierung relevanten Ein- und Ausgangswerte werden in
 sprechende HMI-Variablen kopiert.
===============================================================================
*)
(*
---------------------------------------------------------------------------
Allgemein
---------------------------------------------------------------------------
*)
Konfig_SoftwareVersionPLC := gPlcSwVersion;
Konfig_idNameSteuerung := gPlcKonfigId;
gBetriebsparameter.Allgemein.StandortHoehe := Par_Anlage_Standorthoehe;


(*
---------------------------------------------------------------------------
Standard-Filterzeiten
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.FilterzeitFrischluft := Sensoren_FilterzeitFrischluft;
gBetriebsparameter.Sensoren.FilterzeitAbluft := Sensoren_FilterzeitAbluft;
gBetriebsparameter.Sensoren.FilterzeitTrockenluft := Sensoren_FilterzeitTrockenluft;
gBetriebsparameter.Sensoren.FilterzeitStocktemp := Sensoren_FilterzeitStocktemp;

(*
---------------------------------------------------------------------------
Messbereiche Frischluft
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.FrischlTempMessberMin := Sensoren_FrischlTempMessberMin;
gBetriebsparameter.Sensoren.FrischlTempMessberMax := Sensoren_FrischlTempMessberMax;
gBetriebsparameter.Sensoren.FrischlFeuchtMessberMin := Sensoren_FrischlFeuchteMessberMin;
gBetriebsparameter.Sensoren.FrischlFeuchtMessberMax := Sensoren_FrischlFeuchteMessberMax;

(*
---------------------------------------------------------------------------
Messbereiche Abluft
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.AbluftTempMessberMin := Sensoren_AbluftTempMessberMin;
gBetriebsparameter.Sensoren.AbluftTempMessberMax := Sensoren_AbluftTempMessberMax;
gBetriebsparameter.Sensoren.AbluftFeuchtMessberMin := Sensoren_AbluftFeuchtMessberMin;
gBetriebsparameter.Sensoren.AbluftFeuchtMessberMax := Sensoren_AbluftFeuchtMessberMax;

(*
---------------------------------------------------------------------------
Messbereiche Trockenluft
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.TrockenlTempMessberMin := Sensoren_TrockenlTempMessberMin;
gBetriebsparameter.Sensoren.TrockenlTempMessberMax := Sensoren_TrockenlTempMessberMax;
gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMin := Sensoren_TrockenlFeuchtMessberMin;
gBetriebsparameter.Sensoren.TrockenlFeuchtMessberMax := Sensoren_TrockenlFeuchtMessberMax;

(*
---------------------------------------------------------------------------
Messbereiche Stocktemperatur
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.StocktempMessberMin := Sensoren_StockTempMessberMin;
gBetriebsparameter.Sensoren.StocktempMessberMax := Sensoren_StockTempMessberMax;

(*
---------------------------------------------------------------------------
Sensor-Offsets
---------------------------------------------------------------------------
*)
gBetriebsparameter.Sensoren.OffsetFrischluftTemp := Sensoren_OffsetFrischluftTemp;
gBetriebsparameter.Sensoren.OffsetFrischluftFeuchte := Sensoren_OffsetFrischluftFeuchte;
gBetriebsparameter.Sensoren.OffsetAbluftBox1Temp := Sensoren_OffsetAbluftBox1Temp;
gBetriebsparameter.Sensoren.OffsetAbluftBox1Feuchte := Sensoren_OffsetAbluftBox1Feuchte;
gBetriebsparameter.Sensoren.OffsetAbluftBox2Temp := Sensoren_OffsetAbluftBox2Temp;
gBetriebsparameter.Sensoren.OffsetAbluftBox2Feuchte := Sensoren_OffsetAbluftBox2Feuchte;
gBetriebsparameter.Sensoren.OffsetTrockenluftTemp := Sensoren_OffsetTrockenluftTemp;
gBetriebsparameter.Sensoren.OffsetTrockenluftFeuchte := Sensoren_OffsetTrockenluftFeuchte;
gBetriebsparameter.Sensoren.OffsetStocktemp := Sensoren_OffsetStocktemp;

(*
---------------------------------------------------------------------------
Ausstattung / aktivierte Anlagenteile
---------------------------------------------------------------------------
Diese Werte sind vorläufige Defaultwerte und müssen später an die reale
Anlagenausstattung angepasst werden.
---------------------------------------------------------------------------
*)
gBetriebsparameter.Ausstattung.Box2 := Ausstattung_Box2;
gBetriebsparameter.Ausstattung.Abluftventilator := Ausstattung_Abluftventilator;
gBetriebsparameter.Ausstattung.SensorFrischluft := Ausstattung_SensorFrischluft;
gBetriebsparameter.Ausstattung.SensorAbluftBox1 := Ausstattung_SensorAbluftBox1;
gBetriebsparameter.Ausstattung.SensorAbluftBox2 := Ausstattung_SensorAbluftBox2;
gBetriebsparameter.Ausstattung.SensorTrockenluft := Ausstattung_SensorTrockenluft;
gBetriebsparameter.Ausstattung.SensorStocktemp := Ausstattung_SensorStocktemp;
gBetriebsparameter.Ausstattung.EndlagenVhdBoxenklappe1 := Ausstattung_EndlagenVhdBoxenklappe1;
gBetriebsparameter.Ausstattung.EndlagenVhdBoxenklappe2 := Ausstattung_EndlagenVhdBoxenklappe2;
gBetriebsparameter.Ausstattung.Luftaufbereiter := Ausstattung_Luftaufbereiter_Typ <> KEINER;

(*
---------------------------------------------------------------------------
Ventilator
---------------------------------------------------------------------------
*)
gBetriebsparameter.Ventilator.DrehzahlMin := Par_Ventilator_DrehzahlMin;
