gBetriebsparameter.Boxen[1].StellungKlappe2 := Par_Box1_StellungKlappe2;
gBetriebsparameter.Boxen[2].StellungKlappe1 := Par_Box2_StellungKlappe1;
gBetriebsparameter.Boxen[2].StellungKlappe2 := Par_Box2_StellungKlappe2;

//Stocktemperatur
gBetriebsparameter.Boxen[1].StocktemperaturHysterese := Par_Stocktemperatur_Box1_Hysterese;
gBetriebsparameter.Boxen[2].StocktemperaturHysterese := Par_Stocktemperatur_Box2_Hysterese;

(*
-------------------------------------------------------------------------------
 Verriegelung Box-Betriebsarten (1 Luefter -> nur eine Box gleichzeitig)
 Belegt eine Box den Luefter durchgehend, wird bei der anderen Box
 Dauer-/Intervallbetrieb gesperrt (nur HMI-Hinweis).
-------------------------------------------------------------------------------
*)
// Reset
gStatusAnlage.Box[1].SperreDauerbetrieb     := FALSE;
gStatusAnlage.Box[1].SperreIntervallbetrieb := FALSE;
gStatusAnlage.Box[2].SperreDauerbetrieb     := FALSE;
gStatusAnlage.Box[2].SperreIntervallbetrieb := FALSE;

IF gBetriebsparameter.Ausstattung.Box2 THEN

    // "belegt den Luefter durchgehend" = Dauerbetrieb oder Stocktemperatur
    xBox1BelegtLuefter := gBetriebsparameter.Boxen[1].DauerbetriebEin
                          OR gBetriebsparameter.Boxen[1].StocktemperaturEin;
    xBox2BelegtLuefter := gBetriebsparameter.Boxen[2].DauerbetriebEin
                          OR gBetriebsparameter.Boxen[2].StocktemperaturEin;

    // Box 2 belegt den Luefter -> Box 1 sperren
    IF xBox2BelegtLuefter THEN
        gStatusAnlage.Box[1].SperreDauerbetrieb     := TRUE;
        gStatusAnlage.Box[1].SperreIntervallbetrieb := TRUE;
    ELSIF gBetriebsparameter.Boxen[2].IntervallbetriebEin THEN
        // Intervall der einen Box -> Dauerbetrieb der anderen wuerde stoeren
        gStatusAnlage.Box[1].SperreDauerbetrieb     := TRUE;
    END_IF;

    // Box 1 belegt den Luefter -> Box 2 sperren
    IF xBox1BelegtLuefter THEN
        gStatusAnlage.Box[2].SperreDauerbetrieb     := TRUE;
        gStatusAnlage.Box[2].SperreIntervallbetrieb := TRUE;
    ELSIF gBetriebsparameter.Boxen[1].IntervallbetriebEin THEN
        gStatusAnlage.Box[2].SperreDauerbetrieb     := TRUE;
    END_IF;

END_IF;

// --- HMI-Spiegel ---
