(*
-------------------------------------------------------------------------------
 Zusatzmeldung Anlagenstatus (vereinfacht fuer Lite) - nur Statustext
-------------------------------------------------------------------------------
*)
IF gAktModus = STILLSTAND THEN
    IF gAktoren.xLuftaufbNachlauf AND NOT gAktoren.xFrgLuftaufbereiter THEN
        HMI_Zusatzmeldung_Statustext := ZM_AUSKUEHLZEIT_WLO_AKTIV;      // Auskuehlung laeuft
    ELSIF gCmdAnlage.FehlerStopp THEN
        HMI_Zusatzmeldung_Statustext := ZM_STILLSTAND_FEHLERSTOPP;      // Fehler - kein Start
    ELSE
        HMI_Zusatzmeldung_Statustext := ZM_STILLSTAND_BEREIT;          // bereit
    END_IF;

ELSIF gAktModus = IOTEST THEN
    HMI_Zusatzmeldung_Statustext := ZM_STILLSTAND_IOTEST_NICHT_ABGE;    // I/O-Test aktiv

ELSE   // BETRIEB
    HMI_Zusatzmeldung_Restzeit 	:= 0;   //Kein Countdown
    HMI_Zusatzmeldung_Sanduhr 	:= 0;	//Keine Sanduhr
    IF gCmdAnlage.xTarifAbschaltung THEN
        HMI_Zusatzmeldung_Statustext := ZM_TARIFABSCHALTUNG_AKTIV;
    ELSIF gCmdAnlage.xTarifAbschaltungLuftaufb THEN
        HMI_Zusatzmeldung_Statustext := ZM_FRISCHLUFTB_VLZ_TARIF;
    ELSIF Strombegrenzung.StrombegrenzungEin THEN
        HMI_Zusatzmeldung_Statustext := ZM_STROMBEGRENZUNG_AKTIV;
    ELSIF (gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_1] = STATUS_IN_BEWEGUNG)
       OR (gStatusAnlage.Aktor[AKTOR_KLAPPE_BOX_2] = STATUS_IN_BEWEGUNG) THEN
        HMI_Zusatzmeldung_Statustext := ZM_KLAPPEN_WERDEN_UMGESCHALTET;
        HMI_Zusatzmeldung_Restzeit   := HMI_IN_Box_Aktuell_RestzeitUmschVerzBetriebsart;  
        HMI_Zusatzmeldung_Sanduhr := 1;
    ELSIF gAktoren.xLuftaufbNachlauf AND NOT gAktoren.xFrgLuftaufbereiter THEN
        HMI_Zusatzmeldung_Statustext := ZM_AUSKUEHLZEIT_WLO_AKTIV;
        HMI_Zusatzmeldung_Restzeit   := gAktoren.uRestAuskuehlzeitLuftaufb;   
    ELSE
        HMI_Zusatzmeldung_Statustext := ZM_FRISCHLUFTBETRIEB;
    END_IF;
END_IF;


