	    HMI_OUT_Box_Aktuell_DauerbetriebEin     := FALSE;
	    HMI_OUT_Box_Aktuell_NachtrocknungEin    := FALSE;
	    HMI_OUT_Box_Aktuell_StocktemperaturEin  := FALSE;
	ELSIF rt_Box_Nachtr.Q THEN
	    HMI_OUT_Box_Aktuell_Aus                 := FALSE;
	    HMI_OUT_Box_Aktuell_DauerbetriebEin     := FALSE;
