	xUmschSelAktuell := rt_Box_Aus.Q OR rt_Box_Dauer.Q OR rt_Box_Intervall.Q
	                    OR rt_Box_Nachtr.Q OR rt_Box_Stocktemp.Q;
	TOF_UmschBoxAktuell(IN := xUmschSelAktuell,
