	ELSIF gAktoren.xFrgAbluftventilator THEN
		HMI_Abluft_FarbeIcon := ICON_GELB;
	ELSE 
		HMI_Abluft_FarbeIcon := ICON_GRAU;
	END_IF;
ELSE 
