    gStatusAnlage.Box[1].Status := STATUS_TESTBETRIEB;
ELSIF gBetriebsparameter.Boxen[1].Aus THEN
    gStatusAnlage.Box[1].Status := STATUS_STILLSTAND;
ELSIF gBetriebsparameter.Boxen[1].DauerbetriebEin THEN
    IF gStatusAnlage.Box[1].WetterIstSchlecht
       AND NOT (gBetriebsparameter.Ausstattung.Luftaufbereiter
                AND (gBetriebsparameter.Luftaufbereitung.Typ = HEIZREGISTER OR gBetriebsparameter.Luftaufbereitung.Typ = OFEN)
                AND (gBetriebsparameter.Luftaufbereitung.AutomatikbetriebEin OR gBetriebsparameter.Luftaufbereitung.DauerbetriebEin)) THEN
        IF gBetriebsparameter.Boxen[1].xBoxAktiv THEN
            gStatusAnlage.Box[1].Status := STATUS_SCHLECHTWETTER_LAUF;
        ELSE
            gStatusAnlage.Box[1].Status := STATUS_SCHLECHTWETTER_PAUSE;
        END_IF;
    ELSIF gBetriebsparameter.Boxen[1].xBoxAktiv THEN
        gStatusAnlage.Box[1].Status := STATUS_DAUERBETRIEB;
    ELSE
        gStatusAnlage.Box[1].Status := STATUS_DAUERBETRIEB_PAUSIERT;
    END_IF;
ELSIF gBetriebsparameter.Boxen[1].IntervallbetriebEin THEN
    IF gBetriebsparameter.Boxen[1].xBoxAktiv THEN
        gStatusAnlage.Box[1].Status := STATUS_INTERVALL_LAUF;
    ELSE
        gStatusAnlage.Box[1].Status := STATUS_INTERVALL_PAUSE;
    END_IF;
ELSIF gBetriebsparameter.Boxen[1].NachtrocknungEin THEN
    IF gBetriebsparameter.Boxen[1].xBoxAktiv THEN
        gStatusAnlage.Box[1].Status := STATUS_NACHTROCKNUNG_LAUF;
    ELSE
        gStatusAnlage.Box[1].Status := STATUS_NACHTROCKNUNG_PAUSE;
    END_IF;
ELSIF gBetriebsparameter.Boxen[1].StocktemperaturEin THEN
    IF gBetriebsparameter.Boxen[1].xBoxAktiv THEN
        gStatusAnlage.Box[1].Status := STATUS_STOCKTEMPERATUR_LAUF;       
    ELSE
        gStatusAnlage.Box[1].Status := STATUS_STOCKTEMPERATUR_PAUSE;
    END_IF;
ELSE
    gStatusAnlage.Box[1].Status := STATUS_STILLSTAND;
END_IF;

//BOX 2
// ===================== BOX 2 Status (Text fuer VISU) =====================
IF NOT gBetriebsparameter.Ausstattung.Box2 THEN
    gStatusAnlage.Box[2].Status := STATUS_NICHT_VERFUEGBAR;
ELSIF gCmdAnlage.Test THEN
    gStatusAnlage.Box[2].Status := STATUS_TESTBETRIEB;
ELSIF gBetriebsparameter.Boxen[2].Aus THEN
    gStatusAnlage.Box[2].Status := STATUS_STILLSTAND;
ELSIF gBetriebsparameter.Boxen[2].DauerbetriebEin THEN
    IF gStatusAnlage.Box[2].WetterIstSchlecht
       AND NOT (gBetriebsparameter.Ausstattung.Luftaufbereiter
                AND (gBetriebsparameter.Luftaufbereitung.Typ = HEIZREGISTER OR gBetriebsparameter.Luftaufbereitung.Typ = OFEN)
                AND (gBetriebsparameter.Luftaufbereitung.AutomatikbetriebEin OR gBetriebsparameter.Luftaufbereitung.DauerbetriebEin)) THEN
        IF gBetriebsparameter.Boxen[2].xBoxAktiv THEN
            gStatusAnlage.Box[2].Status := STATUS_SCHLECHTWETTER_LAUF;
        ELSE
            gStatusAnlage.Box[2].Status := STATUS_SCHLECHTWETTER_PAUSE;
        END_IF;
    ELSIF gBetriebsparameter.Boxen[2].xBoxAktiv THEN
        gStatusAnlage.Box[2].Status := STATUS_DAUERBETRIEB;
    ELSE
        gStatusAnlage.Box[2].Status := STATUS_DAUERBETRIEB_PAUSIERT;
    END_IF;
ELSIF gBetriebsparameter.Boxen[2].IntervallbetriebEin THEN
    IF gBetriebsparameter.Boxen[2].xBoxAktiv THEN
        gStatusAnlage.Box[2].Status := STATUS_INTERVALL_LAUF;
    ELSE
        gStatusAnlage.Box[2].Status := STATUS_INTERVALL_PAUSE;
    END_IF;
ELSIF gBetriebsparameter.Boxen[2].NachtrocknungEin THEN
    IF gBetriebsparameter.Boxen[2].xBoxAktiv THEN
        gStatusAnlage.Box[2].Status := STATUS_NACHTROCKNUNG_LAUF;
    ELSE
        gStatusAnlage.Box[2].Status := STATUS_NACHTROCKNUNG_PAUSE;
    END_IF;
ELSIF gBetriebsparameter.Boxen[2].StocktemperaturEin THEN
    IF gBetriebsparameter.Boxen[2].xBoxAktiv THEN
        gStatusAnlage.Box[2].Status := STATUS_STOCKTEMPERATUR_LAUF;
    ELSE
        gStatusAnlage.Box[2].Status := STATUS_STOCKTEMPERATUR_PAUSE;
    END_IF;
ELSE
    gStatusAnlage.Box[2].Status := STATUS_STILLSTAND;
END_IF;

(*
-------------------------------------------------------------------------------
 ALARME fuer Visu aufbereiten ARRAY -> UDINT Maske da Arrays nicht direkt
 an HMI gesendet werden koennen! 
-------------------------------------------------------------------------------
*)

//Reset Bitmasken vor Auswertung
HMI_IN_ALARM_WARNMASKE_1 := fcResetBitmask();
HMI_IN_ALARM_WARNMASKE_2 := fcResetBitmask();
HMI_IN_ALARM_STOERMASKE_1 := fcResetBitmask();
HMI_IN_ALARM_STOERMASKE_2 := fcResetBitmask();

//Array auf Bitmaske fuer HMI schreiben
FOR uIdx := 0 TO 31 DO
	//Erste Warnungsbitmaske [0.31]
	IF (gStatusAnlage.Alarm.ArrWarnung[uIdx]) THEN
		HMI_IN_ALARM_WARNMASKE_1:= fcSetBitInBitmask(Bitmask := HMI_IN_ALARM_WARNMASKE_1, BitNr:= uIdx);
	END_IF;
	//Zweite Warnungsbitmaske [32.63]
	IF (gStatusAnlage.Alarm.ArrWarnung[uIdx + 32]) THEN
		HMI_IN_ALARM_WARNMASKE_2:= fcSetBitInBitmask(Bitmask := HMI_IN_ALARM_WARNMASKE_2, BitNr:= uIdx);
	END_IF;	
	//Erste Stoerungsbitmaske [0.31]
	IF (gStatusAnlage.Alarm.ArrFehler[uIdx]) THEN
		HMI_IN_ALARM_STOERMASKE_1:= fcSetBitInBitmask(Bitmask := HMI_IN_ALARM_STOERMASKE_1, BitNr:= uIdx);
	END_IF;
	//Zweite Stoerungsbitmaske [32.63]
	IF (gStatusAnlage.Alarm.ArrFehler[uIdx + 32]) THEN
		HMI_IN_ALARM_STOERMASKE_2 := fcSetBitInBitmask(Bitmask := HMI_IN_ALARM_STOERMASKE_2, BitNr:= uIdx);
	END_IF;
END_FOR;

data.iecDecl:
PROGRAM HmiMappingCyclic

VAR
	rt_Box_Aus : R_TRIG;
	rt_Box_Dauer : R_TRIG;
	rt_Box_Intervall : R_TRIG;
	rt_Box_Nachtr : R_TRIG;
	rt_Box_Stocktemp : R_TRIG;
	rt_Luftaufb_Auto : R_TRIG;
	rt_Luftaufb_Dauer : R_TRIG;
	rt_Luftaufb_Aus : R_TRIG;
	TOF_UmschBoxAktuell : TOF;   // gemeinsam für Block A/B (schließen sich aus)
    TOF_UmschBox1       : TOF;   // Block C (Einzelbox)
    xUmschSelAktuell    : BOOL;
    xUmschSelBox1       : BOOL;
	lastBoxIndex : USINT;
	uIdx : USINT;
	firstStep : BOOL;
	xBox1BelegtLuefter : BOOL;
    xBox2BelegtLuefter : BOOL;
END_VAR

ST.xhtml:p:
(*
================================================================================
File        : StartStoppCyclic.st
Project     : CControl_Lite
Description :
    Start-/Stopp-Auswertung fuer 2-Box-Anlage.
    Ablauf: 
    	1) Betriebsarten  
    	2) Verriegelung  
    	3) Puls-/Pausebetrieb
        4) Boxaktivitaet  
        5) Start/Stopp
    Hinweis: BerechnungCyclic muss vor diesem Programm aufgerufen werden.
================================================================================
*)

(* ALLGEMEIN *)
usAktStunde := sysClock.hours;
udIntervallMaskeBox1 := Par_Box1_Intervallzeit;
udIntervallMaskeBox2 := Par_Box2_Intervallzeit;
udNachtrocknungMaskeBox1 := Par_Box1_Nachtrocknungszeit;
udNachtrocknungMaskeBox2 := Par_Box2_Nachtrocknungszeit;

xIntervallBox1Anwahl     := FALSE;
xIntervallBox2Anwahl     := FALSE;
xNachtrocknungBox1Anwahl := FALSE;
xNachtrocknungBox2Anwahl := FALSE;
xDauerbetriebBox1Anwahl  := FALSE;
xDauerbetriebBox2Anwahl  := FALSE;
xStocktemperaturBox1Anwahl  := FALSE;
xStocktemperaturBox2Anwahl  := FALSE;

(* Betriebsart *)
gCmdAnlage.Auto := NOT HMI_TEST_doIoTestAktivieren;
gCmdAnlage.Test := HMI_TEST_doIoTestAktivieren;


(*
================================================================================
 PHASE 1 - Betriebsarten ermitteln
 Prioritaet: Nachtrocknung > Intervallbetrieb > Dauerbetrieb
================================================================================
*)

//===== BOX 1 =====
IF gBetriebsparameter.Boxen[1].NachtrocknungEin AND (usAktStunde <= 23) THEN
	//Bitmaske um die aktuelle Stundenanzahl nach rechts schieben und pruefen ob Stunde in Maske aktiv
	xNachtrocknungBox1Anwahl := (SHR(IN := udNachtrocknungMaskeBox1, N := usAktStunde) AND 1) <> 0;

ELSIF gBetriebsparameter.Boxen[1].IntervallbetriebEin AND (usAktStunde <= 23) THEN
	xIntervallBox1Anwahl := (SHR(IN := udIntervallMaskeBox1, N := usAktStunde) AND 1) <> 0;

ELSIF gBetriebsparameter.Boxen[1].StocktemperaturEin THEN
	xStocktemperaturBox1Anwahl := TRUE;

ELSIF gBetriebsparameter.Boxen[1].DauerbetriebEin THEN
	xDauerbetriebBox1Anwahl := TRUE;

END_IF;

//===== BOX 2 =====
IF gBetriebsparameter.Boxen[2].NachtrocknungEin AND (usAktStunde <= 23) THEN
	xNachtrocknungBox2Anwahl := (SHR(IN := udNachtrocknungMaskeBox2, N := usAktStunde) AND 1) <> 0;

ELSIF gBetriebsparameter.Boxen[2].IntervallbetriebEin AND (usAktStunde <= 23) THEN
	xIntervallBox2Anwahl := (SHR(IN := udIntervallMaskeBox2, N := usAktStunde) AND 1) <> 0;

ELSIF gBetriebsparameter.Boxen[2].StocktemperaturEin THEN
	xStocktemperaturBox2Anwahl := TRUE;

ELSIF gBetriebsparameter.Boxen[2].DauerbetriebEin THEN
	xDauerbetriebBox2Anwahl := TRUE;

END_IF;


(*
================================================================================
 PHASE 2 - Verriegelung und Grundfreigabe
 Muss vor der Puls-/Pausezeit stehen, damit die Trocknungszeit nicht
 waehrend einer Sperre oder Stoerung abgezaehlt wird.
================================================================================
*)

// Nachtrocknung hat Vorrang und uebersteuert die jeweils andere (aktive) Box.
// Bei beidseitiger Nachtrocknung mit ueberlappenden Stundenmasken laeuft nur Box 1.
xBox1Freigegeben := gCmdAnlage.Auto
                    AND NOT gCmdAnlage.FehlerStopp
                    AND NOT (xNachtrocknungBox2Anwahl AND NOT xNachtrocknungBox1Anwahl);

xBox2Freigegeben := gCmdAnlage.Auto
                    AND NOT gCmdAnlage.FehlerStopp
                    AND gBetriebsparameter.Ausstattung.Box2
                    AND NOT xNachtrocknungBox1Anwahl;

(*
================================================================================
 PHASE 3 - Stocktemperatur

================================================================================
*)
//===== BOX 1 - Stocktemperatur =====
IF xStocktemperaturBox1Anwahl THEN
    IF gStatusAnlage.StockTemperatur > (gBetriebsparameter.Boxen[1].StocktemperaturSoll + gBetriebsparameter.Boxen[1].StocktemperaturHysterese) THEN
    	xStockHaltBox1 := TRUE;
    ELSIF gStatusAnlage.StockTemperatur < (gBetriebsparameter.Boxen[1].StocktemperaturSoll - gBetriebsparameter.Boxen[1].StocktemperaturHysterese) THEN
        xStockHaltBox1 := FALSE;
    END_IF;
    xStocktemperaturBox1Aktiv := xStockHaltBox1;
ELSE
    xStockHaltBox1      := FALSE;
    xStocktemperaturBox1Aktiv := FALSE;
END_IF;
//===== BOX 2 - Stocktemperatur =====
IF xStocktemperaturBox2Anwahl THEN
    IF gStatusAnlage.StockTemperatur > (gBetriebsparameter.Boxen[2].StocktemperaturSoll + gBetriebsparameter.Boxen[2].StocktemperaturHysterese) THEN
        xStockHaltBox2 := TRUE;
    ELSIF gStatusAnlage.StockTemperatur < (gBetriebsparameter.Boxen[2].StocktemperaturSoll - gBetriebsparameter.Boxen[2].StocktemperaturHysterese) THEN
        xStockHaltBox2 := FALSE;
    END_IF;
    xStocktemperaturBox2Aktiv := xStockHaltBox2;
ELSE
    xStockHaltBox2      := FALSE;
    xStocktemperaturBox2Aktiv := FALSE;
END_IF;


(*
================================================================================
 PHASE 4 - Schlechtwetter Puls-/Pausebetrieb
 Wirkt ausschliesslich auf den Dauerbetrieb. Intervall- und Nachtrocknungs-
 betrieb laufen unveraendert nach Stundenmaske.
================================================================================
*)

//Luftaufbereitung aktiv (Heizregister oder Ofen laeuft in Automatik- oder
//Dauerbetrieb) -> im Automatikbetrieb durchgehend trocknen statt Lauf/Pause.
//Ausnahme: Stellt der Bediener die Luftaufbereitung auf AUS (weder Automatik-
//noch Dauerbetrieb), soll die Witterung mit dem Lauf/Pause-Programm wieder
//greifen -> dann gilt die Luftaufbereitung als nicht aktiv.
//Bewusst ueber die aktiven Betriebsarten abgefragt (nicht ueber '.Aus'), da beim
//Steuerungsstart nicht sicher ist, dass '.Aus' gesetzt ist.
xLuftaufbAktiv := gBetriebsparameter.Ausstattung.Luftaufbereiter
                  AND (gBetriebsparameter.Luftaufbereitung.Typ = HEIZREGISTER
                       OR gBetriebsparameter.Luftaufbereitung.Typ = OFEN)
                  AND (gBetriebsparameter.Luftaufbereitung.AutomatikbetriebEin
                       OR gBetriebsparameter.Luftaufbereitung.DauerbetriebEin);

//===== BOX 1 =====
xSchlechtwetterBox1Aktiv := xDauerbetriebBox1Anwahl
                            AND xBox1Freigegeben
                            AND gStatusAnlage.Box[1].WetterIstSchlecht
                            AND (gStatusAnlage.Box[1].AktSchlechtwetterPause <> 0)
                            AND NOT xLuftaufbAktiv;

fbPulsPauseBox1.Freigabe      := xSchlechtwetterBox1Aktiv;
fbPulsPauseBox1.StartMitPause := FALSE;   //bei Wetterumschlag zuerst trocknen
fbPulsPauseBox1.ZeitPuls      := gStatusAnlage.Box[1].AktSchlechtwetterPuls;
fbPulsPauseBox1.ZeitPause     := gStatusAnlage.Box[1].AktSchlechtwetterPause;
fbPulsPauseBox1();

gStatusAnlage.Box[1].SchlechtwetterPulsOut   := fbPulsPauseBox1.PulsOut;
gStatusAnlage.Box[1].SchlechtwetterPauseOut  := fbPulsPauseBox1.PauseOut;
gStatusAnlage.Box[1].RestSchlechtwetterPuls  := fbPulsPauseBox1.RestzeitPuls;
gStatusAnlage.Box[1].RestSchlechtwetterPause := fbPulsPauseBox1.RestzeitPause;

IF xSchlechtwetterBox1Aktiv THEN
	//Schlechtwetter: nur waehrend der Pulszeit trocknen
	xDauerbetriebBox1Trocknet := fbPulsPauseBox1.PulsOut;
ELSE
	//Schoenwetter oder keine Pausezeit parametriert: Dauerbetrieb
	xDauerbetriebBox1Trocknet := xDauerbetriebBox1Anwahl;
END_IF;

//===== BOX 2 =====
xSchlechtwetterBox2Aktiv := xDauerbetriebBox2Anwahl
                            AND xBox2Freigegeben
                            AND gStatusAnlage.Box[2].WetterIstSchlecht
                            AND (gStatusAnlage.Box[2].AktSchlechtwetterPause <> 0)
                            AND NOT xLuftaufbAktiv;

fbPulsPauseBox2.Freigabe      := xSchlechtwetterBox2Aktiv;
fbPulsPauseBox2.StartMitPause := FALSE;
fbPulsPauseBox2.ZeitPuls      := gStatusAnlage.Box[2].AktSchlechtwetterPuls;
fbPulsPauseBox2.ZeitPause     := gStatusAnlage.Box[2].AktSchlechtwetterPause;
fbPulsPauseBox2();

gStatusAnlage.Box[2].SchlechtwetterPulsOut   := fbPulsPauseBox2.PulsOut;
gStatusAnlage.Box[2].SchlechtwetterPauseOut  := fbPulsPauseBox2.PauseOut;
gStatusAnlage.Box[2].RestSchlechtwetterPuls  := fbPulsPauseBox2.RestzeitPuls;
gStatusAnlage.Box[2].RestSchlechtwetterPause := fbPulsPauseBox2.RestzeitPause;

IF xSchlechtwetterBox2Aktiv THEN
	xDauerbetriebBox2Trocknet := fbPulsPauseBox2.PulsOut;
ELSE
	xDauerbetriebBox2Trocknet := xDauerbetriebBox2Anwahl;
END_IF;


(*
================================================================================
 PHASE 5 - Boxaktivitaet
================================================================================
*)

gBetriebsparameter.Boxen[1].xBoxAktiv := (xDauerbetriebBox1Trocknet
                                          OR xIntervallBox1Anwahl
                                          OR xNachtrocknungBox1Anwahl
                                          OR xStocktemperaturBox1Aktiv)
                                         AND xBox1Freigegeben;

gBetriebsparameter.Boxen[2].xBoxAktiv := (xDauerbetriebBox2Trocknet
                                          OR xIntervallBox2Anwahl
                                          OR xNachtrocknungBox2Anwahl
                                          OR xStocktemperaturBox2Aktiv)
                                         AND xBox2Freigegeben;

xMindEineBoxAktiv := gBetriebsparameter.Boxen[1].xBoxAktiv
                     OR gBetriebsparameter.Boxen[2].xBoxAktiv;


(*
================================================================================
 PHASE 6 - Start/Stopp
================================================================================
*)

(* externe Signale optional, muessen beschrieben werden wenn gewuenscht *)
xExternStart := gCmdAnlage.StartExtern;
xExternStop  := gCmdAnlage.StoppExtern;

(* Fehlerstopp vorerst ohne Alarmmatrix, Variable wird in AlarmCyclic beschrieben *)
//gCmdAnlage.FehlerStopp := FALSE;

//Anlage laeuft solange eine Box aktiv ODER die Luftaufbereitung noch auskuehlt
xAnlageBetrieb := xMindEineBoxAktiv OR gAktoren.xLuftaufbNachlauf;

//Tarifabschaltung wirkt erst, wenn Luftaufbereitung/Auskuehlung/Betriebsmeldung
//abgeschlossen sind (diese haben Vorrang).
xTarifStopWirksam := gCmdAnlage.xTarifAbschaltung AND NOT gAktoren.xLuftaufbNachlauf;

gCmdAnlage.Start := gCmdAnlage.Auto
                    AND (xAnlageBetrieb OR xExternStart)
                    AND NOT gCmdAnlage.FehlerStopp
                    AND NOT xTarifStopWirksam;

gCmdAnlage.Stopp := gCmdAnlage.Auto
                    AND ((NOT xAnlageBetrieb) OR xExternStop
                         OR gCmdAnlage.FehlerStopp
                         OR xTarifStopWirksam);

data.iecDecl:
PROGRAM StartStoppCyclic

VAR
	xMindEineBoxAktiv : BOOL;
	xExternStart : BOOL;
	xExternStop : BOOL;
	xDauerbetriebBox1Anwahl : BOOL;
	xDauerbetriebBox2Anwahl : BOOL;
	xIntervallBox1Anwahl : BOOL;
	xIntervallBox2Anwahl : BOOL;
	xNachtrocknungBox1Anwahl : BOOL;
	xNachtrocknungBox2Anwahl : BOOL;
	xStocktemperaturBox1Anwahl : BOOL;
	xStocktemperaturBox2Anwahl : BOOL;
	xStocktemperaturBox1Aktiv : BOOL;
	xStocktemperaturBox2Aktiv : BOOL;
	xBox1Freigegeben : BOOL;
	xBox2Freigegeben : BOOL;
	xTarifStopWirksam : BOOL;
	usAktStunde : USINT;
	udIntervallMaskeBox1 : UDINT;
	udIntervallMaskeBox2 : UDINT;
	udNachtrocknungMaskeBox1 : UDINT;
	udNachtrocknungMaskeBox2 : UDINT;
	fbPulsPauseBox1 : fbPulsPause;
	xDauerbetriebBox1Trocknet : BOOL;
	xSchlechtwetterBox1Aktiv : BOOL;
	fbPulsPauseBox2 : fbPulsPause;
	xDauerbetriebBox2Trocknet : BOOL;
	xSchlechtwetterBox2Aktiv : BOOL;
	xStockHaltBox1 : BOOL := FALSE;	(* Haltebit Zweipunkt Box 1 *)
	xStockHaltBox2 : BOOL := FALSE;	(* Haltebit Zweipunkt Box 2 *)
	xLuftaufbAktiv : BOOL;   (* Heizregister oder Ofen vorhanden -> kein Puls/Pause *)
	xAnlageBetrieb : BOOL;
END_VAR

ST.xhtml:p:
//SetSysClock (Anforderung kommt von HMI)
IF HMI_OUT_SysClock_ReqSet THEN 
  //Uhrzeit setzen
  retVal :=	sysClockWrite(
  						  seconds 	:= TO_USINT(HMI_OUT_SysClock_seconds), 
						  minutes 	:= TO_USINT(HMI_OUT_SysClock_minutes),
						  hours 	:= TO_USINT(HMI_OUT_SysClock_hours),
						  dayweek 	:= TO_USINT(HMI_OUT_SysClock_dayweek),
						  daymonth 	:= TO_USINT(HMI_OUT_SysClock_daymonth), 
						  month 	:= TO_USINT(HMI_OUT_SysClock_month), 
						  year 		:= TO_USINT(HMI_OUT_SysClock_year)
						  );

END_IF;

IF retVal <> 0 THEN
	HMI_OUT_SysClock_ReqSet := FALSE;
	retVal := 0;
END_IF;

(*
================================================================================
 File        : fbBoxenklappe.st
 Project     : CControl_Lite
 Controller  : Schneider / EcoStruxure Machine Expert HVAC
 Author      : RIG Automation
 Created     : 2026-04-03
 Version     : V0.02
 Description :
    Funktionsbaustein zur Ansteuerung einer Boxenklappe mit einem Wechsler-
    Relais.

    Funktionsprinzip:
      - nicht angesteuert = Richtung A
      - angesteuert       = Richtung B

    Für die Anwendung in CControl_Lite gilt:
      - OeffnenOut     = TRUE
      - SchliessenOut  = FALSE

    Funktionsumfang:
      - Laufzeitüberwachung Öffnen/Schließen
      - Fehlerquittierung
      - Endlagenbehandlung
      - Betrieb auch ohne Endlagen möglich
      - 40 ms Anzugsverzögerung

================================================================================
 Change History
--------------------------------------------------------------------------------
 Version | Date       | Author          | Description
--------------------------------------------------------------------------------
 V0.02   | 2026-04-03 | RIG Automation  | Initialerstellung
================================================================================
*)

IF (NOT Stoerung) THEN

    (*
    ---------------------------------------------------------------------------
    Fehlerquittierung Laufzeitüberwachung
    ---------------------------------------------------------------------------
    *)
    IF QuitFehler OR (LaufzeitOeffnen = 0) OR (NOT EndlagenVhd) THEN
        FehlerLaufzeitOeffnen := FALSE;
    END_IF;

    IF QuitFehler OR (LaufzeitSchliessen = 0) OR (NOT EndlagenVhd) THEN
        FehlerLaufzeitSchliessen := FALSE;
    END_IF;


    CASE uiStep OF

        (*
        =======================================================================
        WARTEN
        =======================================================================
        *)
        0:
            (* state entry *)
            IF stateEntry THEN
                stateEntry := FALSE;
                TON_Laufzeit(IN := FALSE, PT := 0);
                TON_AnzVerz(IN := FALSE, PT := 0);
            END_IF;

            (* state during *)
            IF QuitFehler OR (LaufzeitOeffnen = 0) OR (NOT EndlagenVhd) THEN
                FehlerLaufzeitOeffnen := FALSE;
            END_IF;

            IF QuitFehler OR (LaufzeitSchliessen = 0) OR (NOT EndlagenVhd) THEN
                FehlerLaufzeitSchliessen := FALSE;
            END_IF;

            (* state exit *)
            IF EndlagenVhd OR (LaufzeitOeffnen = 0) THEN
                IF Oeffnen AND NOT FehlerLaufzeitOeffnen THEN
                    stateEntry := TRUE;
                    uiStep  := 1;
                END_IF;
            ELSE
                IF Oeffnen AND NOT KlappeIstOffenOut THEN
                    stateEntry := TRUE;
                    uiStep  := 1;
                END_IF;
            END_IF;

            IF EndlagenVhd OR (LaufzeitSchliessen = 0) THEN
                IF Schliessen AND NOT FehlerLaufzeitSchliessen THEN
                    stateEntry := TRUE;
                    uiStep  := 2;
                END_IF;
            ELSE
                IF Schliessen AND NOT KlappeIstGeschlOut THEN
                    stateEntry := TRUE;
                    uiStep := 2;
                END_IF;
            END_IF;


        (*
        =======================================================================
        OEFFNEN
        =======================================================================
        *)
        1:
            (* state entry *)
            IF stateEntry THEN
                stateEntry := FALSE;
                TON_Laufzeit(IN := FALSE, PT := 0);
                TON_AnzVerz(IN := FALSE, PT := 0);
                FehlerLaufzeitOeffnen := FALSE;
                FehlerLaufzeitSchliessen := FALSE;
                SchliessenOut := FALSE;
                KlappeIstGeschlOut := FALSE;
                KlappeIstOffenOut := FALSE;
            END_IF;

            (* state during *)
            TON_Laufzeit(IN := OeffnenOut AND NOT EndlageOffen, PT := LaufzeitOeffnen);
            TON_AnzVerz(IN := TRUE, PT := 40);
            OeffnenOut := TON_AnzVerz.Q;

            (* state exit *)
            IF (NOT Oeffnen) OR Schliessen OR (TON_Laufzeit.Q AND (LaufzeitOeffnen <> 0)) THEN
                IF (TON_Laufzeit.Q AND (LaufzeitOeffnen <> 0) AND NOT EndlagenVhd) THEN
                    KlappeIstOffenOut := TRUE;
                ELSIF (TON_Laufzeit.Q AND (LaufzeitOeffnen <> 0)) THEN
                    FehlerLaufzeitOeffnen := TRUE;
                END_IF;

                stateEntry := TRUE;
                uiStep  := 0;
            END_IF;


        (*
        =======================================================================
        SCHLIESSEN
        =======================================================================
        *)
        2:
            (* state entry *)
            IF stateEntry THEN
                stateEntry := FALSE;
                TON_Laufzeit(IN := FALSE, PT := 0);
                TON_AnzVerz(IN := FALSE, PT := 0);
                FehlerLaufzeitOeffnen := FALSE;
                FehlerLaufzeitSchliessen := FALSE;
                OeffnenOut := FALSE;
                KlappeIstGeschlOut := FALSE;
                KlappeIstOffenOut := FALSE;
            END_IF;

            (* state during *)
            TON_Laufzeit(IN := SchliessenOut AND NOT EndlageGeschl, PT := LaufzeitSchliessen);
            TON_AnzVerz(IN := TRUE, PT := 40);
            SchliessenOut := TON_AnzVerz.Q;

            (* state exit *)
            IF (NOT Schliessen) OR Oeffnen OR (TON_Laufzeit.Q AND (LaufzeitSchliessen <> 0)) THEN
                IF (TON_Laufzeit.Q AND (LaufzeitSchliessen <> 0) AND NOT EndlagenVhd) THEN
                    KlappeIstGeschlOut := TRUE;
                ELSIF (TON_Laufzeit.Q AND (LaufzeitSchliessen <> 0)) THEN
                    FehlerLaufzeitSchliessen := TRUE;
                END_IF;

                stateEntry := TRUE;
                uiStep := 0;
            END_IF;

    END_CASE;

ELSE
    OeffnenOut := FALSE;
    SchliessenOut := FALSE;
    stateEntry := TRUE;
    FehlerLaufzeitOeffnen := FALSE;
    FehlerLaufzeitSchliessen := FALSE;
    KlappeIstGeschlOut := FALSE;
    KlappeIstOffenOut := FALSE;
    uiStep := 0;
END_IF;

IF (Freigabe = TRUE) THEN
    // Zeitfenster 1 ********************************************************
    FreigZeitfenster1 := FALSE;
    IF (StartZeit1 > StoppZeit1) THEN
        IF (AktZeit >= StartZeit1) OR (AktZeit < StoppZeit1) THEN
            FreigZeitfenster1 := TRUE;
        END_IF;
    ELSE
        IF (AktZeit >= StartZeit1) AND (AktZeit < StoppZeit1) THEN
            FreigZeitfenster1 := TRUE;
        END_IF;
    END_IF;
    // Zeitfenster 2 ********************************************************
    FreigZeitfenster2 := FALSE;
    IF (StartZeit2 > StoppZeit2) THEN
        IF (AktZeit >= StartZeit2) OR (AktZeit < StoppZeit2) THEN
            FreigZeitfenster2 := TRUE;
        END_IF;
    ELSE
        IF (AktZeit >= StartZeit2) AND (AktZeit < StoppZeit2) THEN
            FreigZeitfenster2 := TRUE;
        END_IF;
    END_IF;
    // Zeitfenster 3 ********************************************************
    FreigZeitfenster3 := FALSE;
    IF (StartZeit3 > StoppZeit3) THEN
        IF (AktZeit >= StartZeit3) OR (AktZeit < StoppZeit3) THEN
            FreigZeitfenster3 := TRUE;
        END_IF;
    ELSE
        IF (AktZeit >= StartZeit3) AND (AktZeit < StoppZeit3) THEN
            FreigZeitfenster3 := TRUE;
        END_IF;
    END_IF;
    // Drehzahlbegrenzungen 1 - 3
    IF (FreigZeitfenster1) THEN
        DrehzahlBegrenzung := DrehzahlBegrenzung1;
    ELSIF (FreigZeitfenster2) THEN
        DrehzahlBegrenzung := DrehzahlBegrenzung2;
    ELSIF (FreigZeitfenster3) THEN
        DrehzahlBegrenzung := DrehzahlBegrenzung3;
    ELSE
        DrehzahlBegrenzung := 0.0;
    END_IF;
    StrombegrenzungEin := FreigZeitfenster1 OR FreigZeitfenster2 OR FreigZeitfenster3;
ELSE
    FreigZeitfenster1  := FALSE;
    FreigZeitfenster2  := FALSE;
    FreigZeitfenster3  := FALSE;
    StrombegrenzungEin := FALSE;
    DrehzahlBegrenzung := 0.0;
END_IF;

//Auskühlzeit Warmluftofen, wenn Option Betriebsmeldung nicht vorhanden
TOF_Auskuehlzeit(IN := FreigabeWarmluftofenOut, PT := Auskuehlzeit);

//Restlaufzeit Auskühlung berechnen (für Visu)
RestAuskuehlzeit := Auskuehlzeit - TO_UDINT(TOF_Auskuehlzeit.ET);

//Ausgang für Warmluftofen aktiv
WarmluftofenAktiv := (TOF_Auskuehlzeit.Q AND NOT OptionBetriebsmldgVhd)
                     OR (BetriebsmeldungWarmluftofen AND OptionBetriebsmldgVhd)
                     OR FreigabeWarmluftofenOut;

//Fehlerquittierung
IF QuitFehler THEN
    FehlerSensorAussenluftOut := FALSE;
    FehlerBetriebsmeldungOut  := FALSE;
END_IF;


IF Freigabe THEN

    CASE uStep OF

        //AUS *********************************************************************************************
        0:
            IF stateEntry THEN
                stateEntry              := FALSE;
                FreigabeWarmluftofenOut := FALSE;
                WarmlufttempSollOut     := 0.0;
                TON_VerzBetriebsmeldung(IN := FALSE, PT := 0);
            END_IF;

            //Automatikbetrieb aktiviert
            IF Automatikbetrieb AND NOT FehlerSensorAussenluftOut AND NOT FehlerBetriebsmeldungOut AND NOT FehlerSensorAussenluft THEN
                stateEntry := TRUE;
                uStep       := 1;
            ELSIF Dauerbetrieb AND NOT FehlerSensorAussenluftOut AND NOT FehlerBetriebsmeldungOut THEN
                stateEntry := TRUE;
                uStep       := 2;
            END_IF;


        //AUTOMATIKBETRIEB ********************************************************************************
        1:
            IF stateEntry THEN
                stateEntry := FALSE;
                TON_VerzBetriebsmeldung(IN := FALSE, PT := 0);
            END_IF;

            //Bei Neustart (Wetter nicht gut oder schlecht) ohne Verzögerung umschalten
            IF NOT loc_WetterIstSchlecht AND NOT loc_WetterIstGut THEN
                IF (FrischluftSattDefizitIst < FrischluftSattDefizitSoll) THEN
                    loc_WetterIstSchlecht := TRUE;
                ELSIF (FrischluftSattDefizitIst >= FrischluftSattDefizitSoll) THEN
                    loc_WetterIstGut := TRUE;
                END_IF;
            END_IF;

            //Umschaltverzögerung gutes Wetter / schlechtes Wetter
            TON_WetterIstGut(IN := loc_WetterIstSchlecht AND (FrischluftSattDefizitIst >= (FrischluftSattDefizitSoll + Hysterese)), PT := UmschaltverzWitterung);
            TON_WetterIstSchlecht(IN := loc_WetterIstGut AND (FrischluftSattDefizitIst < (FrischluftSattDefizitSoll - Hysterese)), PT := UmschaltverzWitterung);

            //Flankenauswertung (ersetzt EDGEPOS)
            R_TRIG_WetterIstGut(CLK := TON_WetterIstGut.Q);
            R_TRIG_WetterIstSchlecht(CLK := TON_WetterIstSchlecht.Q);

            IF R_TRIG_WetterIstGut.Q THEN
                loc_WetterIstGut      := TRUE;
                loc_WetterIstSchlecht := FALSE;
            ELSIF R_TRIG_WetterIstSchlecht.Q THEN
                loc_WetterIstGut      := FALSE;
                loc_WetterIstSchlecht := TRUE;
            END_IF;

            //Freigabe Warmluftofen
            FreigabeWarmluftofenOut := loc_WetterIstSchlecht OR WetterIstSchlecht;
            WarmlufttempSollOut     := WarmlufttemperaturVorgabe;

            //Verzögerung Überwachung Betriebsmeldung (Zündzeit)
            TON_VerzBetriebsmeldung(IN := FreigabeWarmluftofenOut AND OptionBetriebsmldgVhd
                              			  AND NOT BetriebsmeldungWarmluftofen
                            			  AND (VerzBetriebsmeldung > 0),
                        			PT := VerzBetriebsmeldung);

            //Fehler keine Betriebsmeldung
            IF TON_VerzBetriebsmeldung.Q THEN
                FehlerBetriebsmeldungOut := TRUE;
                stateEntry := TRUE;
                uStep       := 0;
            //Fehler Sensor Frischluft
            ELSIF FehlerSensorAussenluft THEN
                FehlerSensorAussenluftOut := TRUE;
                stateEntry := TRUE;
                uStep       := 0;
            //Dauerbetrieb aktiv
            ELSIF Dauerbetrieb THEN
                stateEntry := TRUE;
                uStep       := 2;
            //Kein Automatikbetrieb
            ELSIF NOT Automatikbetrieb THEN
                stateEntry := TRUE;
                uStep       := 0;
            END_IF;


        //DAUERBETRIEB ***********************************************************************************
        2:
            IF stateEntry THEN
                stateEntry := FALSE;
                TON_VerzBetriebsmeldung(IN := FALSE, PT := 0);
            END_IF;

            //Freigabe Warmluftofen
            FreigabeWarmluftofenOut := TRUE;
            WarmlufttempSollOut     := WarmlufttemperaturVorgabe;

            //Verzögerung Überwachung Betriebsmeldung (Zündzeit)
            TON_VerzBetriebsmeldung(IN := FreigabeWarmluftofenOut AND OptionBetriebsmldgVhd AND NOT BetriebsmeldungWarmluftofen, PT := VerzBetriebsmeldung);

            //Fehler
            IF TON_VerzBetriebsmeldung.Q THEN
                FehlerBetriebsmeldungOut := TRUE;
                stateEntry := TRUE;
                uStep       := 0;
            //Automatikbetrieb aktiv
            ELSIF Automatikbetrieb THEN
                stateEntry := TRUE;
                uStep       := 1;
            //Kein Dauerbetrieb
            ELSIF NOT Dauerbetrieb THEN
                stateEntry := TRUE;
                uStep       := 0;
            END_IF;

    END_CASE;

ELSE

    FreigabeWarmluftofenOut   := FALSE;
    WarmlufttempSollOut       := 0.0;
    uStep                      := 0;
    stateEntry                := TRUE;
    FehlerSensorAussenluftOut := FALSE;
    FehlerBetriebsmeldungOut  := FALSE;

END_IF;

IF Freigabe THEN

    //Fehlerquittierung
    IF QuitFehler THEN
        FehlerOut := FALSE;
    END_IF;


    CASE uStep OF

        //AUS *********************************************************************************************
        0:
            IF stateEntry THEN
                stateEntry              := FALSE;
                FreigabeHeizregisterOut := FALSE;
                DrehzahlHeizregisterOut := 0.0;
            END_IF;

            //Automatikbetrieb aktiviert
            IF Automatikbetrieb AND NOT FehlerOut AND NOT FehlerSensorAussenluft THEN
                stateEntry := TRUE;
                uStep       := 1;
            ELSIF Dauerbetrieb AND NOT FehlerOut THEN
                stateEntry := TRUE;
                uStep       := 2;
            END_IF;


        //AUTOMATIKBETRIEB ********************************************************************************
        1:
            IF stateEntry THEN
                stateEntry := FALSE;
            END_IF;

            //Bei Neustart (Wetter nicht gut oder schlecht) ohne Verzögerung umschalten
            IF NOT loc_WetterIstSchlecht AND NOT loc_WetterIstGut THEN
                IF (FrischluftSattDefizitIst < FrischluftSattDefizitSoll) THEN
                    loc_WetterIstSchlecht := TRUE;
                ELSIF (FrischluftSattDefizitIst >= FrischluftSattDefizitSoll) THEN
                    loc_WetterIstGut := TRUE;
                END_IF;
            END_IF;

            //Umschaltverzögerung gutes Wetter / schlechtes Wetter
            TON_WetterIstGut(IN := loc_WetterIstSchlecht AND (FrischluftSattDefizitIst >= (FrischluftSattDefizitSoll + Hysterese)), PT := UmschaltverzWitterung);
            TON_WetterIstSchlecht(IN := loc_WetterIstGut AND (FrischluftSattDefizitIst < (FrischluftSattDefizitSoll - Hysterese)), PT := UmschaltverzWitterung);

            //Flankenauswertung (ersetzt EDGEPOS)
            R_TRIG_WetterIstGut(CLK := TON_WetterIstGut.Q);
            R_TRIG_WetterIstSchlecht(CLK := TON_WetterIstSchlecht.Q);

            IF R_TRIG_WetterIstGut.Q THEN
                loc_WetterIstGut      := TRUE;
                loc_WetterIstSchlecht := FALSE;
            ELSIF R_TRIG_WetterIstSchlecht.Q THEN
                loc_WetterIstGut      := FALSE;
                loc_WetterIstSchlecht := TRUE;
            END_IF;

            //Freigabe Heizregister
            FreigabeHeizregisterOut := loc_WetterIstSchlecht OR WetterIstSchlecht;
            DrehzahlHeizregisterOut := DrehzahlHeizregisterSoll;

            //Fehler
            IF FehlerSensorAussenluft THEN
                FehlerOut  := TRUE;
                stateEntry := TRUE;
                uStep       := 0;
            //Dauerbetrieb aktiv
            ELSIF Dauerbetrieb THEN
                stateEntry := TRUE;
                uStep       := 2;
            //Kein Automatikbetrieb
            ELSIF NOT Automatikbetrieb THEN
                stateEntry := TRUE;
                uStep       := 0;
            END_IF;


        //DAUERBETRIEB ***********************************************************************************
        2:
            IF stateEntry THEN
                stateEntry := FALSE;
            END_IF;

            //Freigabe Heizregister
            FreigabeHeizregisterOut := TRUE;
            DrehzahlHeizregisterOut := DrehzahlHeizregisterSoll;

            //Automatikbetrieb aktiv
            IF Automatikbetrieb THEN
                stateEntry := TRUE;
                uStep       := 1;
            //Kein Dauerbetrieb
            ELSIF NOT Dauerbetrieb THEN
                stateEntry := TRUE;
                uStep       := 0;
            END_IF;

    END_CASE;


ELSE

    FreigabeHeizregisterOut := FALSE;
    DrehzahlHeizregisterOut := 0.0;
    uStep                    := 0;
    stateEntry              := TRUE;
    FehlerOut               := FALSE;

END_IF;

IF Freigabe THEN

	Gueltig    := TRUE;
	loc_TempK  := 273.15 + LuftTemperatur;
	loc_Nenner := 237.3  + LuftTemperatur;

	(* rel. Feuchte hart begrenzen - Sensorausreisser sonst durchgereicht *)
	loc_rF := LuftRelFeuchte;
	IF loc_rF < 0.0   THEN loc_rF := 0.0;   END_IF;
	IF loc_rF > 100.0 THEN loc_rF := 100.0; END_IF;


	(* --- Luftdruck [hPa] ------------------------------------------- *)
	(* p = p0 * (1 - 0.0065*h/288.15)^5.255                            *)
	loc_Basis := 1.0 - 0.0065 * MeterUeberAdria / 288.15;
	IF loc_Basis > 0.001 THEN
		LuftdruckUmgebung := CONST_MATH_DRUCK_MEERESHOEHE
		                     * EXP(5.255 * LN(loc_Basis));
	ELSE
		LuftdruckUmgebung := CONST_MATH_MAX_VALUE;
		Gueltig           := FALSE;
	END_IF;


	(* --- Luftdichte [kg/m³] ---------------------------------------- *)
	IF (loc_TempK > 0.001) AND (LuftdruckUmgebung < CONST_MATH_MAX_VALUE) THEN
		LuftDichte := (LuftdruckUmgebung * 100.0) / (287.058 * loc_TempK);
	ELSE
		LuftDichte := CONST_MATH_MAX_VALUE;
		Gueltig    := FALSE;
	END_IF;


	(* --- Saettigungsdampfdruck [mbar] ------------------------------ *)
	(* Magnus: es = 6.1078 * 10^(7.5*T/(237.3+T))                      *)
	IF loc_Nenner > 0.001 THEN
		LuftDampfdruckSatt := 6.1078
		                      * EXP(C_LN10 * 7.5 * LuftTemperatur / loc_Nenner);
	ELSE
		LuftDampfdruckSatt := CONST_MATH_MAX_VALUE;
		Gueltig            := FALSE;
	END_IF;


	(* --- Wasserdampfdruck [mbar] ----------------------------------- *)
	IF LuftDampfdruckSatt < CONST_MATH_MAX_VALUE THEN
		LuftDampfdruckH2O := LuftDampfdruckSatt * (loc_rF / 100.0);
	ELSE
		LuftDampfdruckH2O := CONST_MATH_MAX_VALUE;
		Gueltig           := FALSE;
	END_IF;


	(* --- absolute Feuchte gesaettigt [g/m³] ------------------------ *)
	IF (LuftDampfdruckSatt < CONST_MATH_MAX_VALUE) AND (loc_TempK > 0.001) THEN
		LuftAbsoluteFeuchteSatt := 216.67 * LuftDampfdruckSatt / loc_TempK;
	ELSE
		LuftAbsoluteFeuchteSatt := CONST_MATH_MAX_VALUE;
		Gueltig                 := FALSE;
	END_IF;


	(* --- absolute Feuchte [g/m³] ----------------------------------- *)
	IF LuftAbsoluteFeuchteSatt < CONST_MATH_MAX_VALUE THEN
		LuftAbsoluteFeuchte_g_m3 := (loc_rF / 100.0) * LuftAbsoluteFeuchteSatt;
	ELSE
		LuftAbsoluteFeuchte_g_m3 := CONST_MATH_MAX_VALUE;
		Gueltig                  := FALSE;
	END_IF;


	(* --- Saettigungsdefizit [g/m³] --------------------------------- *)
	IF LuftAbsoluteFeuchte_g_m3 < CONST_MATH_MAX_VALUE THEN
		LuftSaettigungsdefizit := LuftAbsoluteFeuchteSatt - LuftAbsoluteFeuchte_g_m3;
	ELSE
		LuftSaettigungsdefizit := CONST_MATH_MAX_VALUE;
		Gueltig                := FALSE;
	END_IF;


	(* --- absolute Feuchte [g/kg] ----------------------------------- *)
	IF (LuftAbsoluteFeuchte_g_m3 < CONST_MATH_MAX_VALUE)
	   AND (LuftDichte < CONST_MATH_MAX_VALUE) AND (LuftDichte > 0.001) THEN
		LuftAbsoluteFeuchte_g_kg := LuftAbsoluteFeuchte_g_m3 / LuftDichte;
	ELSE
		LuftAbsoluteFeuchte_g_kg := CONST_MATH_MAX_VALUE;
		Gueltig                  := FALSE;
	END_IF;


	(* --- Taupunkttemperatur [°C] ----------------------------------- *)
	IF (LuftDampfdruckH2O < CONST_MATH_MAX_VALUE) AND (LuftDampfdruckH2O > 0.001) THEN
		loc_Taupunkttemp := LN(LuftDampfdruckH2O) / C_LN10;   (* log10 *)
		IF (8.233 - loc_Taupunkttemp) > 0.001 THEN
			TaupunktTemp := (234.67 * loc_Taupunkttemp - 184.2)
			                / (8.233 - loc_Taupunkttemp);
		ELSE
			TaupunktTemp := CONST_MATH_MAX_VALUE;
			Gueltig      := FALSE;
		END_IF;
	ELSE
		TaupunktTemp := CONST_MATH_MAX_VALUE;
		Gueltig      := FALSE;
	END_IF;

ELSE

	LuftdruckUmgebung        := CONST_MATH_MAX_VALUE;
	LuftAbsoluteFeuchteSatt  := CONST_MATH_MAX_VALUE;
	LuftAbsoluteFeuchte_g_kg := CONST_MATH_MAX_VALUE;
	LuftAbsoluteFeuchte_g_m3 := CONST_MATH_MAX_VALUE;
	LuftDichte               := CONST_MATH_MAX_VALUE;
	TaupunktTemp             := CONST_MATH_MAX_VALUE;
	LuftDampfdruckH2O        := CONST_MATH_MAX_VALUE;
	LuftDampfdruckSatt       := CONST_MATH_MAX_VALUE;
	LuftSaettigungsdefizit   := CONST_MATH_MAX_VALUE;
	Gueltig                  := FALSE;

END_IF;

(********************************************************************
 * fbCControlWitterung - Portierung für EcoStruxure Machine Expert - HVAC
 ********************************************************************
 * Generierung der Witterungsverhaeltnisse aus Saettigungsdefizit
 * und Trocknungslaufzeit (Materialfeuchte-Stufe)
 ********************************************************************)

 IF Freigabe THEN

	(* --- Aktuell gueltige Stufe aus der Trockengutfeuchte ---------- *)
	(* Setzt eine ABSTEIGEND sortierte Schwellwerttabelle voraus!      *)
	StufeAktuell := 1;
	IF MaterialfeuchteIst <> 0 THEN
		FOR i := 1 TO 5 DO
			IF MaterialfeuchteIst <= MaterialfeuchteStufe[i] THEN
				StufeAktuell := i + 1;
			END_IF;
		END_FOR;
	END_IF;


	(* --- Puls-/Pausezeiten durchreichen ---------------------------- *)
	SchlechtwetterPulszeit  := SchlechtwetterPulszeitAktuell;
	SchlechtwetterPausezeit := SchlechtwetterPausezeitAktuell;


	(* --- Gueltigen Sensor bestimmen -------------------------------- *)
	SensorGueltig := TRUE;

	IF (AuswahlSensor = 1) AND SensorFrischluftVhd THEN
		SaettigungsdefizitIst := FrischluftSaettigungsdefizit;
	ELSIF (AuswahlSensor = 2) AND SensorTrockenluftVhd THEN
		SaettigungsdefizitIst := TrockenluftSaettigungsdefizit;
	(* Ausgewaehlter Sensor nicht vhd. -> Ersatzsensor in fester Reihenfolge *)
	ELSIF SensorFrischluftVhd THEN
		SaettigungsdefizitIst := FrischluftSaettigungsdefizit;
	ELSIF SensorTrockenluftVhd THEN
		SaettigungsdefizitIst := TrockenluftSaettigungsdefizit;
	ELSE
		SaettigungsdefizitIst := 0.0;
		SensorGueltig         := FALSE;   (* kein Sensor verfuegbar *)
	END_IF;


	(* --- Witterungsverhaeltnisse bestimmen ------------------------- *)
	IF SensorGueltig THEN

		loc_WetterIstGut      := FALSE;
		loc_WetterIstSchlecht := FALSE;

		IF SaettigungsdefizitIst >= (GrenzwertStufeAktuell + HystereseGrenzwert) THEN
			loc_WetterIstGut := TRUE;
		ELSIF SaettigungsdefizitIst <= (GrenzwertStufeAktuell - HystereseGrenzwert) THEN
			loc_WetterIstSchlecht := TRUE;
		END_IF;

		CASE curStep OF

		(* --- INIT --- *)
		0:
			TON_SchrittWitterung(IN := FALSE);
			stateEntry := TRUE;
			IF loc_WetterIstGut THEN
				curStep := 1;
			ELSE
				curStep := 2;
			END_IF;

		(* --- Wetter ist gut --- *)
		1:
			IF stateEntry THEN
				stateEntry := FALSE;
				TON_SchrittWitterung(IN := FALSE);
			END_IF;

			WetterIstGut      := TRUE;
			WetterIstSchlecht := FALSE;

			TON_SchrittWitterung(IN := loc_WetterIstSchlecht,
			                     PT := VerzWetterwechsel);

			IF TON_SchrittWitterung.Q THEN
				stateEntry := TRUE;
				curStep    := 2;
			END_IF;

		(* --- Wetter ist schlecht --- *)
		2:
			IF stateEntry THEN
				stateEntry := FALSE;
				TON_SchrittWitterung(IN := FALSE);
			END_IF;

			WetterIstGut      := FALSE;
			WetterIstSchlecht := TRUE;

			TON_SchrittWitterung(IN := loc_WetterIstGut,
			                     PT := VerzWetterwechsel);

			IF TON_SchrittWitterung.Q THEN
				stateEntry := TRUE;
				curStep    := 1;
			END_IF;

		ELSE
			curStep    := 0;      (* Schrittkette defensiv zuruecksetzen *)
			stateEntry := TRUE;

		END_CASE;

	ELSE
		(* Kein gueltiger Sensor -> Normalbetrieb, kein Schlechtwetter *)
		loc_WetterIstGut      := FALSE;
		loc_WetterIstSchlecht := FALSE;
		WetterIstGut          := TRUE;
		WetterIstSchlecht     := FALSE;
		TON_SchrittWitterung(IN := FALSE);
		stateEntry := TRUE;
		curStep    := 0;
	END_IF;


(* --- keine Freigabe des Bausteins --------------------------------- *)
ELSE
	loc_WetterIstGut        := FALSE;
	loc_WetterIstSchlecht   := FALSE;
	WetterIstGut            := FALSE;
	WetterIstSchlecht       := FALSE;
	SensorGueltig           := FALSE;
	TON_SchrittWitterung(IN := FALSE);
	stateEntry              := TRUE;
	curStep                 := 0;
	SaettigungsdefizitIst   := 0.0;
	SchlechtwetterPulszeit  := 0;
	SchlechtwetterPausezeit := 0;
	StufeAktuell            := 1;
END_IF;

IF Freigabe THEN

	(* --- Sonderfaelle ohne Schrittkette ---------------------------- *)
	IF ZeitPause = 0 THEN
		(* keine Pause parametriert -> durchgehend trocknen *)
		PulsOut       := TRUE;
		PauseOut      := FALSE;
		RestzeitPuls  := ZeitPuls;
		RestzeitPause := 0;
		TON_PulsPause(IN := FALSE, PT := 0);
		curStep       := 0;
		stateEntry    := TRUE;

	ELSIF ZeitPuls = 0 THEN
		(* keine Laufzeit parametriert -> Box bleibt aus *)
		PulsOut       := FALSE;
		PauseOut      := TRUE;
		RestzeitPuls  := 0;
		RestzeitPause := ZeitPause;
		TON_PulsPause(IN := FALSE, PT := 0);
		curStep       := 0;
		stateEntry    := TRUE;

	ELSE

		CASE curStep OF

		(* --- INIT --- *)
		0:
			TON_PulsPause(IN := FALSE, PT := 0);
			stateEntry := TRUE;
			IF StartMitPause THEN
				curStep := 2;
			ELSE
				curStep := 1;
			END_IF;

		(* --- PULS: Box trocknet --- *)
		1:
			IF stateEntry THEN
				stateEntry := FALSE;
				TON_PulsPause(IN := FALSE, PT := 0);
			END_IF;

			PulsOut  := TRUE;
			PauseOut := FALSE;

			TON_PulsPause(IN := TRUE, PT := ZeitPuls);

			IF TON_PulsPause.Q THEN
				stateEntry := TRUE;
				curStep    := 2;
			END_IF;

		(* --- PAUSE: Box steht --- *)
		2:
			IF stateEntry THEN
				stateEntry := FALSE;
				TON_PulsPause(IN := FALSE, PT := 0);
			END_IF;

			PulsOut  := FALSE;
			PauseOut := TRUE;

			TON_PulsPause(IN := TRUE, PT := ZeitPause);

			IF TON_PulsPause.Q THEN
				stateEntry := TRUE;
				curStep    := 1;
			END_IF;

		ELSE
			curStep    := 0;
			stateEntry := TRUE;

		END_CASE;


		(* --- Restzeiten fuer die HMI-Anzeige --- *)
		IF stateEntry THEN
			(* Schrittwechsel: Timer wird erst im naechsten Zyklus gestartet *)
			RestzeitPuls  := ZeitPuls;
			RestzeitPause := ZeitPause;
		ELSE
			loc_ET_ms := TON_PulsPause.ET;

			IF curStep = 1 THEN
				IF ZeitPuls > loc_ET_ms THEN
					RestzeitPuls := ZeitPuls - loc_ET_ms;
				ELSE
					RestzeitPuls := 0;
				END_IF;
				RestzeitPause := ZeitPause;
			ELSE
				RestzeitPuls := ZeitPuls;
				IF ZeitPause > loc_ET_ms THEN
					RestzeitPause := ZeitPause - loc_ET_ms;
				ELSE
					RestzeitPause := 0;
				END_IF;
			END_IF;
		END_IF;

	END_IF;

ELSE
	(* keine Freigabe -> Schrittkette ruecksetzen *)
	PulsOut       := FALSE;
	PauseOut      := FALSE;
	RestzeitPuls  := 0;
	RestzeitPause := 0;
	TON_PulsPause(IN := FALSE, PT := 0);
	curStep       := 0;
	stateEntry    := TRUE;
END_IF;

IF Freigabe THEN
    ZeitfensterAktiv := ZeitfensterIn[AktuelleStunde];

    (* Ende des aktuellen (gleichbleibenden) Blocks heute suchen *)
    stundeEndeTag := 23;
    FOR i := TO_INT(AktuelleStunde) + 1 TO 23 DO
        IF ZeitfensterIn[i] <> ZeitfensterAktiv THEN
            stundeEndeTag := i - 1;
            EXIT;
        END_IF;
    END_FOR;

    (* Restminuten heute *)
    minRestTag := 60 - AktuelleMinute;
    IF stundeEndeTag > TO_INT(AktuelleStunde) THEN
        minRestTag := minRestTag + TO_UINT(stundeEndeTag - TO_INT(AktuelleStunde)) * 60;
    END_IF;

    (* Folgetag nur, wenn Block bis 23 Uhr durchlaeuft *)
    minRestFolgetag := 0;
    IF stundeEndeTag = 23 THEN
        FOR ii := 0 TO 23 DO
            IF ZeitfensterIn[ii] = ZeitfensterAktiv THEN
                minRestFolgetag := minRestFolgetag + 60;
            ELSE
                EXIT;
            END_IF;
        END_FOR;
    END_IF;

    minRestGesamt := minRestTag + minRestFolgetag;
    restStd := minRestGesamt / 60;
    IF restStd <= 24 THEN
        RestzeitStundenOut := restStd;
        RestzeitMinutenOut := minRestGesamt - (restStd * 60);
    ELSE
        RestzeitStundenOut := 65535;   (* >24h -> keine Anzeige *)
        RestzeitMinutenOut := 65535;
    END_IF;
ELSE
    ZeitfensterAktiv   := FALSE;
    RestzeitStundenOut := 65535;
    RestzeitMinutenOut := 65535;
END_IF;

IF Reset THEN
    Sekunden := 0;  Minuten := 0;  Stunden := 0;
ELSIF (Aktiv AND sekTick) THEN
    IF Sekunden < 59 THEN
        Sekunden := Sekunden + 1;
    ELSE
        Sekunden := 0;
        IF Minuten < 59 THEN
            Minuten := Minuten + 1;
        ELSE
            Minuten := 0;
            Stunden := Stunden + 1;
        END_IF;
    END_IF;
END_IF;

// Bitstelle in Wert umwandeln
ValBit := SHL(UDINT#1, BitNr);

// Bit in Bitmaske setzen
fcSetBitInBitmask := Bitmask OR ValBit;

// Bitstelle in Wert umwandeln
ValBit := SHL(UDINT#1, BitNr);

// Bit in Bitmaske löschen
fcClearBitInBitmask := Bitmask AND NOT ValBit;
